  ui_story_5057_50570102_68_dialog_content = "Você...",
  ui_story_5057_50570102_69_dialog_content = "O que eu preciso fazer para me fazer entender por você?",
  ui_story_5057_50570102_70_dialog_content = "Não estou falando da amizade comum, mas do tipo de negócios entre adultos...",
  ui_story_5057_50570102_71_dialog_content = "(O quê...? Deixei ela brava?)",
  ui_story_5057_50570102_72_dialog_content = "<color=#e8d9bb>Rosnar-</color>",
  ui_story_5057_50570102_73_dialog_content = "O que foi?",
  ui_story_5057_50570102_74_dialog_content = "Desculpe, não comi desde esta manhã.",
  ui_story_5057_50570102_75_dialog_content = "Ahem, bem, vamos pegar algo para morder então.",
  ui_story_5057_50570102_76_dialog_content = "...",
  ui_story_5057_50570102_77_dialog_content = "...",
  ui_story_5057_50570102_78_dialog_content = "...",
  ui_story_5057_50570102_79_dialog_content = "(Ela está com o rosto enterrado na comida e isso está tão constrangedor... Será que ela ainda está brava comigo?)",
  ui_story_5057_50570102_80_dialog_content = "(Os pratos estão deliciosos, mas essa é a primeira vez que a vejo comendo sem dizer uma palavra.)",
  ui_story_5057_50570102_81_dialog_content = "(Opa, nossos olhares se cruzaram! Preciso baixar minha cabeça!)",
  ui_story_5057_50570102_82_dialog_content = "Ahem, então...",
  ui_story_5057_50570102_83_dialog_content = "O churrasco está delicioso... Eu pedi para você. Experimente.",
  ui_story_5057_50570102_84_dialog_content = "<color=#e8d9bb>Terminando a frase, Lorelei mergulha de volta e dá uma grande mordida na carne.</color>",
  ui_story_5057_50570102_85_dialog_content = "Ah, claro, entendi, valeu!",
  ui_story_5057_50570102_86_dialog_content = "E, Lorelei, sobre o que aconteceu lá atrás...",
  ui_story_5057_50570102_87_dialog_content = "Eu não quis dizer que não quero ser seu amigo, PlayerName.",
  ui_story_5057_50570102_88_dialog_content = "É só que eu quero me apresentar como uma pessoa madura nos negócios, em vez de alguém que só sai com amigos como uma criança.",
  ui_story_5057_50570102_89_dialog_content = "Eu quero me desligar—",
  ui_story_5057_50570102_90_option_content = "Entendi.",
  ui_story_5057_50570102_91_dialog_content = "Entendo que você se esforça para conquistar o reconhecimento dos outros como uma pessoa independente.",
  ui_story_5057_50570102_92_dialog_content = "Mas... eu ainda não sou adulto! Quando estiver comigo, você não precisa ser maduro como um adulto. Apenas relaxe e seja você mesmo.",
  ui_story_5057_50570102_93_dialog_content = "Obrigado, PlayerName...",
  ui_story_5057_50570102_94_option_content = "Está tudo bem.",
  ui_story_5057_50570102_95_dialog_content = "Eu sei o que você quer dizer. Não se preocupe, eu não vou levar a sério. É normal que amigos discutam de vez em quando!",
  ui_story_5057_50570102_96_dialog_content = "Você ainda está disposto a ser meu amigo? Obrigado, PlayerName.",
  ui_story_5057_50570102_97_dialog_content = "<color=#e8d9bb>Depois disso, Lorelei volta ao seu normal, rindo e conversando comigo enquanto aproveitamos nossa comida. Ela até me faz companhia e conversa comigo até tarde da noite.</color>",
  ui_story_5057_50570201_1_dialog_content = "Ei, acho que você é o ajudante que o Lorelei mencionou?",
  ui_story_5057_50570201_2_dialog_content = "Ei, acho que Cena é a pessoa que precisa de ajuda que Lorelei mencionou?",
  ui_story_5057_50570201_3_dialog_content = "Ah, você está me imitando agora, Celestita.",
  ui_story_5057_50570201_4_dialog_content = "Por quê? Você está tentando exalar o charme e carisma maduro de um homem como eu?",
  ui_story_5057_50570201_5_dialog_content = "Mas isso não se encaixa na sua categoria de idade, Celestita.",
  ui_story_5057_50570201_6_dialog_content = "Não é isso!",
  ui_story_5057_50570201_7_dialog_content = "Não seja narcisista! Eu estava apenas sendo sarcástico.",
  ui_story_5057_50570201_8_dialog_content = "Eu não ligo para o seu charme ou seja lá o que for.",
  ui_story_5057_50570201_9_dialog_content = "É mesmo? Há muitas senhoras que não concordariam.",
  ui_story_5057_50570201_10_dialog_content = "Você vai ter problemas nos relacionamentos mais cedo ou mais tarde com essa atitude.",
  ui_story_5057_50570201_11_dialog_content = "Hahaha, essa é uma afirmação estranha.",
  ui_story_5057_50570201_12_dialog_content = "Se você me perguntar, a dor da rejeição é um fato da vida para todos nós compartilharmos.",
  ui_story_5057_50570201_13_dialog_content = "A vida é curta, então aproveite!",
  ui_story_5057_50570201_14_dialog_content = "Eu não acredito nisso. EveAté a pessoa mais casual teria sentimentos e desejo por um relacionamento estável e harmonioso.",
  ui_story_5057_50570201_15_dialog_content = "É isso que as pessoas normais pensam.",
  ui_story_5057_50570201_16_dialog_content = "Eu sou diferente, pois sou Cena.",
  ui_story_5057_50570201_17_dialog_content = "Suspiro, isso não parece encantador. Vamos nos concentrar nos negócios.",
  ui_story_5057_50570201_18_dialog_content = "Como diz o ditado, \"As coisas mudam e nada permanece igual.\"",
  ui_story_5057_50570201_19_dialog_content = "O que eu amo é passear e experimentar diferentes experiências.",
  ui_story_5057_50570201_20_dialog_content = "Relacionamentos estáticos só colocam algemas nas minhas asas.",
  ui_story_5057_50570201_21_dialog_content = "Sério?",
  ui_story_5057_50570201_22_dialog_content = "Quanto mais você tenta se apresentar como um grande amante, mais parece que você depende de uma fachada cativante para evitar encarar a realidade.",
  ui_story_5057_50570201_23_dialog_content = "Aham.",
  ui_story_5057_50570201_24_dialog_content = "É por isso que vocês Celestitas são problemáticos.",
  ui_story_5057_50570201_25_dialog_content = "O código do silêncio também é uma medida de adultos maduros, você sabe. Caso contrário, não há felicidade na vida.",
  ui_story_5057_50570201_26_dialog_content = "Oh, eu estava pensando em como seria encantador ter uma senhora adorável me ajudando, transformando nosso tempo juntos em um encontro romântico.",
  ui_story_5057_50570201_27_dialog_content = "Mas agora eu acabo com uma criança espertinha que consegue ler mentes.",
  ui_story_5057_50570201_28_dialog_content = "Então, que tal irmos tomar uma rodada ou duas, talvez diminuir um pouco esse poder psíquico seu?",
  ui_story_5057_50570201_29_dialog_content = "Estou aqui para trabalhar, não para namorar ou beber como certa pessoa.",
  ui_story_5057_50570201_30_dialog_content = "Trabalho?",
  ui_story_5057_50570201_31_dialog_content = "Ainda é de manhã, não é hora de trabalhar ainda! Vamos nos divertir primeiro.",
  ui_story_5057_50570201_32_dialog_content = "Eu conheço um lugar incrível que com certeza vai te surpreender.",
  ui_story_5057_50570201_33_dialog_content = "O Dragão da Noite Clara... de fato, um lugar que me deixaria impressionado.",
  ui_story_5057_50570201_34_option_content = "Vai andar comigo?",
  ui_story_5057_50570201_35_dialog_content = "Desculpe, PlayerName, não tenho interesse em andar com um adolescente como você.",
  ui_story_5057_50570201_36_dialog_content = "Então qual é o combinado...",
  ui_story_5057_50570201_37_option_content = "O que deveríamos fazer?",
  ui_story_5057_50570201_38_dialog_content = "Calma. Eu já escolhi o primeiro alvo.",
  ui_story_5057_50570201_39_dialog_content = "Meus olhos são tão afiados quanto uma águia treinada...",
  ui_story_5057_50570201_40_dialog_content = "Então, e aquela senhora encantadora ali, com um garoto e uma garota?",
  ui_story_5057_50570201_41_dialog_content = "(Olho na direção e vejo uma jovem e bela mãe pronta para entrar na fila com um garoto e sua irmãzinha a reboque.)",
  ui_story_5057_50570201_42_dialog_content = "(Eles parecem muito felizes, apesar de estarem no meio de uma multidão lotada.)",
  ui_story_5057_50570201_43_dialog_content = "Você não vai flertar, vai?",
  ui_story_5057_50570201_44_dialog_content = "Precisa ser mais esperto do que isso.",
  ui_story_5057_50570201_45_dialog_content = "Oi, senhora encantadora, essas são suas crianças? Eles pareciam muito interessados no brinquedo grande.",
  ui_story_5057_50570201_46_dialog_content = "Sim, eles dois estão se divertindo muito aqui! Este resort de férias é realmente incrível!",
  ui_story_5057_50570201_47_dialog_content = "Como gerente do Denuo Valley Resort, fico feliz em ouvir isso!",
  ui_story_5057_50570201_48_dialog_content = "Portanto, preciso garantir que você e os dois jovens convidados aproveitem ao máximo o valor do seu dinheiro!",
  ui_story_5057_50570201_49_dialog_content = "Aqui estão três vouchers VIP para você.",
  ui_story_5057_50570201_50_dialog_content = "Ah, gerente, você é incrivelmente... Ei!",
  ui_story_5057_50570201_51_dialog_content = "Cuide bem desta senhora e dos irmãos, PlayerName!",
  ui_story_5057_50570201_52_dialog_content = "<color=#e8d9bb>De repente, Cena empurra os três em minha direção e rapidamente alcança os dois rapazes que acabaram de roubar a bolsa da mãe.</color>",
  ui_story_5057_50570201_53_dialog_content = "Hã?",
  ui_story_5057_50570201_54_dialog_content = "Nem pensar em fugir daqui!",
  ui_story_5057_50570201_55_dialog_content = "<color=#e8d9bb>Cena acerta um chute bem na cintura do ladrão mais próximo.</color>",
  ui_story_5057_50570201_56_dialog_content = "<color=#e8d9bb>O ladrão que levou um chute sai voando e bate diretamente em seu amigo, e ambos caem juntos.</color>",
  ui_story_5057_50570201_57_dialog_content = "D-Droga!",
  ui_story_5057_50570201_58_dialog_content = "Finalmente te peguei. Como ousa mirar na senhora sob minha vigilância.",
  ui_story_5057_50570201_59_dialog_content = "Mas tudo bem, agora você tem todo o tempo do mundo para se arrepender.",
  ui_story_5057_50570201_60_dialog_content = "Muito obrigado!",
  ui_story_5057_50570201_61_dialog_content = "É minha obrigação. Valorizamos a segurança de todos os hóspedes no resort acima de tudo.",
  ui_story_5057_50570201_62_dialog_content = "Especialmente para uma senhora tão encantadora quanto você.",
  ui_story_5057_50570201_63_dialog_content = "Tudo bem, podemos sair agora, jovem Celestita.",
  ui_story_5057_50570201_64_dialog_content = "Comparado a mim, que já capturei um ladrão lendário como detetive particular, você se saiu bem.",
  ui_story_5057_50570201_65_dialog_content = "Tenha orgulho de si mesmo!",
  ui_story_5057_50570201_66_dialog_content = "O quê? O que eu fiz?",
  ui_story_5057_50570201_67_dialog_content = "<color=#e8d9bb>Depois disso, Cena me convida para jantar. Nós comemos enquanto ele fala sem parar sobre como aquela senhora era linda e hipnotizante.</color>",
  ui_story_5057_50570201_68_dialog_content = "<color=#e8d9bb>Ainda assim, ele não transforma esse afeto em ação, e a história de Cena com aquela senhora chega ao fim assim mesmo.</color>",
  ui_story_5057_50570202_1_dialog_content = "Bom dia.",
  ui_story_5057_50570202_2_dialog_content = "Bom dia, Celestita.",
  ui_story_5057_50570202_3_dialog_content = "O que você está fazendo em um lugar como este tão cedo pela manhã? Eu tenho procurado por você em todos os lugares.",
  ui_story_5057_50570202_4_dialog_content = "Onde mais eu estaria senão em um bar? Ficar em uma piscina? Isso não é bom para a minha pele.",
  ui_story_5057_50570202_5_dialog_content = "O que quero dizer é, você não tem trabalho a fazer?",
  ui_story_5057_50570202_6_dialog_content = "Você tem tentado me fazer enrolar com você tão descaradamente, seria um milagre se o Lorelei não descontasse meu salário...",
  ui_story_5057_50570202_7_dialog_content = "Hahaha, você é ótimo em todos os aspectos, além de ser muito metido.",
  ui_story_5057_50570202_8_dialog_content = "Você não sabe como viver a vida ao máximo? Com a quantia insignificante que Lorelei está me pagando, é melhor eu ficar em uma lanchonete, esperando por um encontro maravilhoso.",
  ui_story_5057_50570202_9_dialog_content = "Então, quando a \"ela\" que você está esperando vai aparecer?",
  ui_story_5057_50570202_10_dialog_content = "Ei, tire sua mente dos bueiros agora, Celestita.",
  ui_story_5057_50570202_11_dialog_content = "Não seja tão superficial. Apenas fazer amigos também é maravilhoso.",
  ui_story_5057_50570202_12_dialog_content = "Estou perplexo com a forma como você conseguiu transformar isso em minha culpa.",
  ui_story_5057_50570202_13_dialog_content = "Hahaha, você é uma pessoa tão interessante.",
  ui_story_5057_50570202_14_dialog_content = "Não fique aí parado, venha até aqui. Eu não vou te devorar vivo.",
  ui_story_5057_50570202_15_dialog_content = "Não me diga que você está intimidado pelo meu ar de sofisticação... Ou será que você simplesmente não gosta das características de semi-humano em mim?",
  ui_story_5057_50570202_16_dialog_content = "Isso não é verdade!",
  ui_story_5057_50570202_17_dialog_content = "Ai está. Eu aprecio o fato de você não ter medo nem mesmo de um Auroriano como eu!",
  ui_story_5057_50570202_18_dialog_content = "Hã? Quanto você tem bebido? Ainda está sóbrio?",
  ui_story_5057_50570202_19_dialog_content = "Nenhuma gota. Vamos ao trabalho.",
  ui_story_5057_50570202_20_dialog_content = "Uau, a mudança repentina para a seriedade... Não estou acostumado com isso.",
  ui_story_5057_50570202_21_dialog_content = "Vamos lá, PlayerName, como eu acabei de dizer, você é ótimo em todos os aspectos.",
  ui_story_5057_50570202_22_dialog_content = "Mas você ainda é muito inocente quando se trata de amor e romance. Estou preocupado se você conseguirá encontrar seu próprio final feliz.",
  ui_story_5057_50570202_23_dialog_content = "Eu não sou inocente... Even mesmo que eu seja, não é da sua conta!",
  ui_story_5057_50570202_24_dialog_content = "Não diga isso. Somos amigos e eu não suporto ver você jogando sua vida fora.",
  ui_story_5057_50570202_25_dialog_content = "Após uma reflexão profunda durante a noite, decidi passar todos os meus segredos para você.",
  ui_story_5057_50570202_26_dialog_content = "Hã, bom...",
  ui_story_5057_50570202_27_option_content = "Eu posso concordar com isso.",
  ui_story_5057_50570202_28_dialog_content = "É o Caelestite que eu conheço. Não se preocupe em me chamar de mestre. Vamos direto ao assunto.",
  ui_story_5057_50570202_29_option_content = "Não, obrigado.",
  ui_story_5057_50570202_30_dialog_content = "Não seja tão inflexível. Aprender nunca é algo ruim.",
  ui_story_5057_50570202_31_dialog_content = "A-Tudo bem...",
  ui_story_5057_50570202_32_dialog_content = "Tudo bem, teremos que criar um cenário...",
  ui_story_5057_50570202_33_dialog_content = "S-Segure!",
  ui_story_5057_50570202_34_dialog_content = "Nem pense em me fazer me vestir para isso!",
  ui_story_5057_50570202_35_dialog_content = "Hmm, essa é uma ótima ideia... Você tem certeza de que não quer?",
  ui_story_5057_50570202_36_dialog_content = "Parou!",
  ui_story_5057_50570202_37_dialog_content = "Está bem. Afinal, você é meu primeiro aluno.",
  ui_story_5057_50570202_38_dialog_content = "Então, vamos começar com as teorias e princípios.",
  ui_story_5057_50570202_39_dialog_content = "Primeiro, você deve ter coragem para se aproximar dela, saber elogiar e mostrar que valoriza suas qualidades.",
  ui_story_5057_50570202_40_dialog_content = "Elogio... Como eu faço isso?",
  ui_story_5057_50570202_41_dialog_content = "Tente citações poéticas, por exemplo.",
  ui_story_5057_50570202_42_dialog_content = "\"Você é tão lindo e inebriante quanto uma lua prateada.\"",
  ui_story_5057_50570202_43_dialog_content = "\"Seu sorriso rivaliza com um pôr do sol deslumbrante.\"",
  ui_story_5057_50570202_44_dialog_content = "Algo nesse sentido.",
  ui_story_5057_50570202_45_dialog_content = "Ok, acho que entendi o básico. E então?",
  ui_story_5057_50570202_46_dialog_content = "O próximo movimento é arrasador. Você precisa ser charmoso como eu para conseguir realizá-lo.",
  ui_story_5057_50570202_47_dialog_content = "Você cruza seu olhar com o dela, com paixão desenfreada.",
  ui_story_5057_50570202_48_dialog_content = "Derreta-a com seu olhar.",
  ui_story_5057_50570202_49_dialog_content = "Pisque suavemente e envie sinais.",
  ui_story_5057_50570202_50_dialog_content = "Ou se você acha que é charmoso o suficiente, pode mandar um beijo para ela.",
  ui_story_5057_50570202_51_dialog_content = "Ninguém poderia resistir a isso!",
  ui_story_5057_50570202_52_dialog_content = "Ah, não estou me sentindo bem agora...",
  ui_story_5057_50570202_53_dialog_content = "Então, você sentiu o quão poderoso isso é?",
  ui_story_5057_50570202_54_dialog_content = "Sim...",
  ui_story_5057_50570202_55_dialog_content = "Então vem o terceiro movimento. Você deve ser resiliente ou ter muito pouca vergonha.",
  ui_story_5057_50570202_56_dialog_content = "Você precisa ter a coragem de se gabar nos momentos certos.",
  ui_story_5057_50570202_57_dialog_content = "E jogar de vez em quando algumas frases descaradas, mas engraçadas, fará com que mais pessoas gostem de você.",
  ui_story_5057_50570202_58_dialog_content = "Encontrar uma senhora como você deve ser minha recompensa por salvar a Astra!",
  ui_story_5057_50570202_59_dialog_content = "Sim, eu admito que é um pouco clichê, mas você precisa aprender que eles adoram elogios!",
  ui_story_5057_50570202_60_dialog_content = "Acho que ouvir você é minha punição por talvez ter destruído Astra na vida anterior...",
  ui_story_5057_50570202_61_dialog_content = "Nada mal, você aprende rápido!",
  ui_story_5057_50570202_62_dialog_content = "Você está perto de se formar agora. Eu vou te levar para um teste de campo mais tarde.",
  ui_story_5057_50570202_63_dialog_content = "Não acredito que estou realmente aqui...",
  ui_story_5057_50570202_64_dialog_content = "Eu só queria aprender algo inútil... Isso não é uma coisa ruim, certo?",
  ui_story_5057_50570202_65_dialog_content = "Então, onde está o Cena? Ele está atrasado...",
  ui_story_5057_50570202_66_dialog_content = "PlayerName！",
  ui_story_5057_50570202_67_dialog_content = "Desculpe, estou atrasado.",
  ui_story_5057_50570202_68_dialog_content = "Lorelei me agarrou para falar sobre trabalho. Eu tive que fazer um grande esforço para me soltar.",
  ui_story_5057_50570202_69_dialog_content = "Você não está esperando há muito tempo, não é? Aqui está um chocolate que peguei da mesa do Lorelei.",
  ui_story_5057_50570202_70_dialog_content = "Não, acabei de chegar aqui... Ah, obrigado.",
  ui_story_5057_50570202_71_dialog_content = "Venha, PlayerName, me diga em quem você está interessado entre o público.",
  ui_story_5057_50570202_72_dialog_content = "Uh, estamos fazendo isso de verdade? Eu não gosto de abordar estranhos com essa intenção em mente...",
  ui_story_5057_50570202_73_dialog_content = "Não pense demais. É apenas um treino, não prejudica ninguém.",
  ui_story_5057_50570202_74_dialog_content = "Mas se você ainda está preocupado com isso, devemos abortar.",
  ui_story_5057_50570202_75_dialog_content = "Alguém que não aproveita o processo nunca pode esperar influenciar a presa.",
  ui_story_5057_50570202_76_dialog_content = "Mas já que estamos aqui, por que nós dois não aproveitamos e nos divertimos?",
  ui_story_5057_50570202_77_dialog_content = "Nós dois?",
  ui_story_5057_50570202_78_dialog_content = "Estou bem com isso, mas tenho a sensação de que você armou tudo isso...",
  ui_story_5057_50570202_79_dialog_content = "O que vocês dois estão fazendo aqui?",
  ui_story_5057_50570202_80_dialog_content = "Lorelei?!</translation>",
  ui_story_5057_50570202_81_dialog_content = "Cena saiu correndo de alegria, então eu segui.",
  ui_story_5057_50570202_82_dialog_content = "Eu tinha certeza de que ele estava paquerando garotas novamente. Quem é a vítima desta vez?",
  ui_story_5057_50570202_83_dialog_content = "Você errou. Estou apenas curtindo com PlayerName hoje.",
  ui_story_5057_50570202_84_dialog_content = "Saindo? Não tente me enganar.",
  ui_story_5057_50570202_85_dialog_content = "Vamos lá, me machuca profundamente que meu chefe não confia em mim.",
  ui_story_5057_50570202_86_dialog_content = "Volte comigo e pare de corromper o Celestita!",
  ui_story_5057_50570202_87_dialog_content = "Bem bem...",
  ui_story_5057_50570202_88_dialog_content = "Faremos isso novamente mais tarde, PlayerName!",
  ui_story_5057_50570202_89_dialog_content = "Não tem de novo!",
  ui_story_5057_50570202_90_dialog_content = "Hã? Eles foram embora assim, só isso?",
  ui_story_5057_50570202_91_dialog_content = "<color=#e8d9bb>Depois, Cena me pede para sair e fazer sua aula novamente... Não acredito que ele seja uma pessoa tão evasiva.</color>",
  ui_story_5057_50570301_1_dialog_content = "Hmm, sinto algo muito familiar vindo do público bem ali.",
  ui_story_5057_50570301_2_dialog_content = "A sensação de tomar banho na luz do sol cintilante e cercado por plantas exuberantes na floresta...",
  ui_story_5057_50570301_3_dialog_content = "Olá, PlayerName, que surpresa encontrá-lo tão cedo.",
  ui_story_5057_50570301_4_dialog_content = "Naroxel! Eu sabia que era você!",
  ui_story_5057_50570301_5_dialog_content = "Você parece surpreso.",
  ui_story_5057_50570301_6_dialog_content = "Ah, não, de jeito nenhum.",
  ui_story_5057_50570301_7_dialog_content = "Como posso explicar...",
  ui_story_5057_50570301_8_dialog_content = "Estou um pouco surpreso que eu pude sentir você sem usar minhas habilidades psíquicas, Naroxel.",
  ui_story_5057_50570301_9_dialog_content = "O ar único que você tem... é muito distinto.",
  ui_story_5057_50570301_10_dialog_content = "Ah...?",
  ui_story_5057_50570301_11_dialog_content = "(Opa, acabei de dizer algo ofensivo?)",
  ui_story_5057_50570301_12_dialog_content = "Posso considerar que você tem uma boa impressão de mim, PlayerName?",
  ui_story_5057_50570301_13_dialog_content = "Ah, sim, com certeza!",
  ui_story_5057_50570301_14_dialog_content = "Isso pode ser porque nós, Celestitas, somos próximos da natureza.",
  ui_story_5057_50570301_15_dialog_content = "O que explica por que sinto afinidade por você quando te vejo.",
  ui_story_5057_50570301_16_dialog_content = "Entendi. Fico feliz que você pense tão bem de mim.",
  ui_story_5057_50570301_17_dialog_content = "A propósito, você está livre agora, PlayerName?",
  ui_story_5057_50570301_18_dialog_content = "Nesse caso, gostaria de pedir que me mostrasse o parque.",
  ui_story_5057_50570301_19_dialog_content = "Tenho vários dias de folga e vou passá-los neste resort.",
  ui_story_5057_50570301_20_dialog_content = "Mas ainda estou pouco familiarizado com os brinquedos maiores e não sei como relaxar completamente.",
  ui_story_5057_50570301_21_dialog_content = "Imagino que seria muito mais feliz com você na companhia.",
  ui_story_5057_50570301_22_option_content = "Claro, sem problemas!",
  ui_story_5057_50570301_23_dialog_content = "Conheço o resort inteiro como a palma da minha mão!",
  ui_story_5057_50570301_24_dialog_content = "Deixe-me planejar um passeio especial guiado por Caelestite para você.",
  ui_story_5057_50570301_25_option_content = "Bom...",
  ui_story_5057_50570301_26_dialog_content = "Você tem outros negócios para cuidar?",
  ui_story_5057_50570301_27_dialog_content = "Então não devo te segurar...",
  ui_story_5057_50570301_28_dialog_content = "De jeito nenhum! Eu estava apenas planejando um passeio especial guiado por Caelestite para você.",
  ui_story_5057_50570301_29_dialog_content = "Então, estou contando com você, PlayerName.",
  ui_story_5057_50570301_30_dialog_content = "Ufa... Não acredito que estou encharcado da cabeça aos pés.",
  ui_story_5057_50570301_31_dialog_content = "O que você acha deste passeio rápido Bluefire Lava?",
  ui_story_5057_50570301_32_dialog_content = "Enquanto te leva lá do alto pela corrente, você é atingido por jatos quentes de água.",
  ui_story_5057_50570301_33_dialog_content = "Combine isso com uma paisagem que imita um vulcão e efeitos de iluminação e som bem projetados...",
  ui_story_5057_50570301_34_dialog_content = "É certo que recriará a emoção de escapar de um vulcão prestes a entrar em erupção!",
  ui_story_5057_50570301_35_dialog_content = "Como você está se sentindo, Naroxel? A empolgação tirou todo o estresse dos seus ombros?",
  ui_story_5057_50570301_36_dialog_content = "Foi muito emocionante, de fato.",
  ui_story_5057_50570301_37_dialog_content = "Isso me lembrou de uma tarefa de mensageiro quando cruzei com um vulcão em erupção.",
  ui_story_5057_50570301_38_dialog_content = "Foi extremamente perigoso. Eu tinha uma mochila cheia e acelerei com tudo que tinha.",
  ui_story_5057_50570301_39_dialog_content = "Eu quase encontrei a ruína algumas vezes antes de finalmente fugir das proximidades e preservar as mensagens intactas.",
  ui_story_5057_50570301_40_dialog_content = "Evemesmo entregando tudo a tempo...",
  ui_story_5057_50570301_41_dialog_content = "Minhas roupas estavam chamuscadas. Ainda me lembro de como foi horrível para mim.",
  ui_story_5057_50570301_42_dialog_content = "Não são muitas pessoas que conseguem fazer isso, Naroxel...",
  ui_story_5057_50570301_43_dialog_content = "Acho que esse passeio não é tão incrível para você. Vamos para o próximo!",
  ui_story_5057_50570301_44_dialog_content = "Ufa... que tal este?",
  ui_story_5057_50570301_45_dialog_content = "O Brain Blender apresenta 22 quedas livres... Esse número é supostamente baseado em... *retch*",
  ui_story_5057_50570301_46_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5057_50570301_47_dialog_content = "Tô bem, valeu...",
  ui_story_5057_50570301_48_dialog_content = "Eu estava tão tonto naquele passeio, quase desmaiei, mas você estava curtindo a paisagem como se não fosse nada...",
  ui_story_5057_50570301_49_dialog_content = "Para ser honesto, foi a primeira vez que aproveitei a vista dessa altura.",
  ui_story_5057_50570301_50_dialog_content = "Então, não pude evitar me envolver completamente.",
  ui_story_5057_50570301_51_dialog_content = "Hmm, parece que passeios assim são muito tranquilos para você, Naroxel...",
  ui_story_5057_50570301_52_dialog_content = "Céus, essa máquina é insana! Minhas dentaduras douradas novíssimas quase foram arremessadas da minha boca!",
  ui_story_5057_50570301_53_dialog_content = "Você chama isso de insano? Eu já ouvi falar de uma criança que foi jogada na piscina e simplesmente desapareceu.",
  ui_story_5057_50570301_54_dialog_content = "Depois disso, todos que andassem no Brain Blender e chegassem ao topo sem fechar os olhos ouviriam seus soluços à noite.",
  ui_story_5057_50570301_55_dialog_content = "...",
  ui_story_5057_50570301_56_dialog_content = "Naroxel?",
  ui_story_5057_50570301_57_dialog_content = "N-Nada.",
  ui_story_5057_50570301_58_dialog_content = "De onde você ouviu isso? Não é um parque de diversões novo? Como poderia haver um acidente assim?",
  ui_story_5057_50570301_59_dialog_content = "Olha, está escrito bem ali naquela placa, \"Lenda do Liquidificador de Cérebros.\"",
  ui_story_5057_50570301_60_dialog_content = "Não acredito que você compartilhe conteúdo promocional com os outros como se fosse uma história verdadeira...",
  ui_story_5057_50570301_61_dialog_content = "...",
  ui_story_5057_50570301_62_dialog_content = "Haha, acho que é só uma história Cena inventada para promover o passeio.",
  ui_story_5057_50570301_63_dialog_content = "Então, para onde devemos ir agora? Há muitos outros brinquedos emocionantes por aqui!",
  ui_story_5057_50570301_64_dialog_content = "Desculpe ser indelicado, mas há algum lugar próximo para descanso?",
  ui_story_5057_50570301_65_dialog_content = "Há um pequeno camping perto daqui com plantas exuberantes.",
  ui_story_5057_50570301_66_dialog_content = "Gostaria de ir lá, por favor.",
  ui_story_5057_50570301_67_dialog_content = "Ufa, um local tão verdejante é realmente relaxante.",
  ui_story_5057_50570301_68_dialog_content = "Você se importa se eu deitar um pouco?",
  ui_story_5057_50570301_69_dialog_content = "Não mesmo!",
  ui_story_5057_50570301_70_dialog_content = "Todas as caronas que você me deu foram muito divertidas e emocionantes.",
  ui_story_5057_50570301_71_dialog_content = "Mas eu me sinto realmente à vontade aqui, especialmente quando você está comigo.",
  ui_story_5057_50570301_72_dialog_content = "O que eu gostaria de dizer é, espero não ter estragado o passeio especial que você planejou para mim.",
  ui_story_5057_50570301_73_dialog_content = "Sem chance. Enquanto você estiver feliz, eu estarei feliz.",
  ui_story_5057_50570301_74_dialog_content = "(Aquele sentimento de estar cercado por plantas exuberantes quando conheci Naroxel se tornou uma realidade tangível...)",
  ui_story_5057_50570301_75_dialog_content = "Acho que estou totalmente imerso em todo esse verde...",
  ui_story_5057_50570301_76_dialog_content = "Zzzzz...",
  ui_story_5057_50570301_77_dialog_content = "Hã?",
  ui_story_5057_50570301_78_dialog_content = "(Naroxel adormeceu.)",
  ui_story_5057_50570301_79_dialog_content = "(O rosto dela é sereno e calmo, até tem um sorriso.)",
  ui_story_5057_50570301_80_dialog_content = "Hmm...",
  ui_story_5057_50570301_81_dialog_content = "(Eu deveria deixá-la sozinha por enquanto...)",
  ui_story_5057_50570301_82_dialog_content = "<color=#e8d9bb>Mais tarde, fico preocupado que Naroxel possa sentir frio, então a cubro com minhas roupas.</color>",
  ui_story_5057_50570302_1_dialog_content = "Desculpe, PlayerName, eu não quis cochilar.",
  ui_story_5057_50570302_2_dialog_content = "Não se preocupe. Você está muito melhor agora.",
  ui_story_5057_50570302_3_dialog_content = "Sim, faz muito tempo que eu não conseguia relaxar nesse ambiente.",
  ui_story_5057_50570302_4_dialog_content = "Sinto-me descansado tanto fisicamente quanto mentalmente.",
  ui_story_5057_50570302_5_dialog_content = "Isso é maravilhoso.",
  ui_story_5057_50570302_6_dialog_content = "Na verdade, eu tenho um pedido...",
  ui_story_5057_50570302_7_dialog_content = "Me avise e vou tentar o meu melhor.",
  ui_story_5057_50570302_8_dialog_content = "Podemos pular todos os brinquedos radicais depois?",
  ui_story_5057_50570302_9_dialog_content = "Claro!",
  ui_story_5057_50570302_10_dialog_content = "Para algo que é menos do que um passeio emocionante, podemos experimentar a roda-gigante.",
  ui_story_5057_50570302_11_dialog_content = "Ele tem vista para todo o resort, e a vista do topo é ótima!",
  ui_story_5057_50570302_12_dialog_content = "Ou se você deseja natureza, o deque de observação do cânion é uma opção.",
  ui_story_5057_50570302_13_dialog_content = "Possui uma paisagem magnífica com muitas trilhas para caminhadas.",
  ui_story_5057_50570302_14_dialog_content = "Ah, e tem a floresta ribeirinha abaixo do cânion. Você vai adorar com certeza.",
  ui_story_5057_50570302_15_dialog_content = "É perto de onde estamos agora.",
  ui_story_5057_50570302_16_dialog_content = "Floresta ribeirinha... Isso realmente parece relaxante e reconfortante.",
  ui_story_5057_50570302_17_dialog_content = "Vamos lá.",
  ui_story_5057_50570302_18_dialog_content = "Que encantador isso é...",
  ui_story_5057_50570302_19_dialog_content = "O riacho límpido e a floresta exuberante podem realmente relaxar você.",
  ui_story_5057_50570302_20_dialog_content = "O rico aroma das plantas no ar também é revigorante.",
  ui_story_5057_50570302_21_dialog_content = "Obrigado, PlayerName, por me mostrar a bela paisagem.",
  ui_story_5057_50570302_22_dialog_content = "Que bom que gostou.",
  ui_story_5057_50570302_23_dialog_content = "Venha aqui, PlayerName.",
  ui_story_5057_50570302_24_dialog_content = "O que foi?",
  ui_story_5057_50570302_25_dialog_content = "Aqui está a pimenta, que pode ser usada como tempero depois de moída.",
  ui_story_5057_50570302_26_dialog_content = "É picante e um ótimo complemento para pratos no inverno.",
  ui_story_5057_50570302_27_dialog_content = "Este é o konjac, que supostamente pode despertar sua mente. É comido em muitos lugares.",
  ui_story_5057_50570302_28_dialog_content = "Ah, e essa árvore aqui, sua fibra é flexível e durável o suficiente para ser transformada em cordas de arco.",
  ui_story_5057_50570302_29_dialog_content = "Eu não sabia que você tinha um entendimento tão profundo sobre plantas, Naroxel.",
  ui_story_5057_50570302_30_dialog_content = "Bem, os entregadores às vezes encontram situações inesperadas em suas entregas.",
  ui_story_5057_50570302_31_dialog_content = "Então, faz parte do nosso trabalho aprender coisas que podem ajudar os outros.",
  ui_story_5057_50570302_32_dialog_content = "Mensageiro parece ser uma escolha de carreira muito impressionante...",
  ui_story_5057_50570302_33_dialog_content = "Hahaha... Dove não sai da minha cabeça quando penso em entregadores, provavelmente porque ela deixou uma grande impressão em mim.",
  ui_story_5057_50570302_34_dialog_content = "Dove gosta de enrolar, mas ela te ajudou bastante, não foi?",
  ui_story_5057_50570302_35_dialog_content = "Isso me lembra! O Lumâmbar no início era do Dove.",
  ui_story_5057_50570302_36_dialog_content = "Fico feliz que os mensageiros tenham desempenhado um papel em sua jornada, PlayerName.",
  ui_story_5057_50570302_37_dialog_content = "Ah, olhe bem ali.",
  ui_story_5057_50570302_38_dialog_content = "As folhas têm um padrão distinto. Pode ser uma espécie única desta área.",
  ui_story_5057_50570302_39_dialog_content = "Ah é? Deixe-me ver.",
  ui_story_5057_50570302_40_dialog_content = "(Naroxel parece diferente hoje de alguma forma, mas não consigo identificar exatamente o que é...)",
  ui_story_5057_50570302_41_dialog_content = "PlayerName?",
  ui_story_5057_50570302_42_dialog_content = "Desculpe! Não quis encarar, apenas viajei por um segundo!",
  ui_story_5057_50570302_43_dialog_content = "Está muito úmido no oásis, às vezes causando falta de ar e perda de concentração.",
  ui_story_5057_50570302_44_dialog_content = "Vamos seguir em frente.",
  ui_story_5057_50570302_45_dialog_content = "Claro. Preste atenção nos seus passos e não tropece.",
  ui_story_5057_50570302_46_dialog_content = "Obrigado pelo lembrete.",
  ui_story_5057_50570302_47_dialog_content = "(Eu vi coisas?)",
  ui_story_5057_50570302_48_dialog_content = "(Havia tristeza nos olhos de Naroxel.)",
  ui_story_5057_50570302_49_dialog_content = "Na verdade... estou muito feliz em passar as férias com você, PlayerName.",
  ui_story_5057_50570302_50_dialog_content = "O quê?",
  ui_story_5057_50570302_51_dialog_content = "Eu tenho uma afeição pelos Celestitas e seu modo de vida há muito tempo.",
  ui_story_5057_50570302_52_dialog_content = "Porque eu tenho o sangue típico de semi-humanos que é avesso ao inverno, mas nasci em Northland...",
  ui_story_5057_50570302_53_dialog_content = "Sempre desejei o agradável e eternamente temperado Eraveil.",
  ui_story_5057_50570302_54_dialog_content = "Mas quando eu fiz uma entrega lá, estava irreconhecível e sem vida...",
  ui_story_5057_50570302_55_dialog_content = "Sim...",
  ui_story_5057_50570302_56_option_content = "Mas não vou desistir da minha casa.",
  ui_story_5057_50570302_57_dialog_content = "Eraveil significa tudo para mim e um dia restaurarei sua glória.",
  ui_story_5057_50570302_58_option_content = "Agora está em ruínas.",
  ui_story_5057_50570302_59_dialog_content = "Não tenho certeza se tenho o que é preciso para restaurá-lo à glória passada.",
  ui_story_5057_50570302_60_dialog_content = "Você deve acreditar em si mesmo e em seus amigos.",
  ui_story_5057_50570302_61_dialog_content = "Você está certo, Naroxel.",
  ui_story_5057_50570302_62_dialog_content = "Eu sabia que não estava errado sobre você.",
  ui_story_5057_50570302_63_dialog_content = "Estou feliz que você não fugiu de suas responsabilidades e escolheu reconstruir Eraveil.",
  ui_story_5057_50570302_64_dialog_content = "Sei que haverá muitos obstáculos pela frente, mas você tem minha ajuda.",
  ui_story_5057_50570302_65_dialog_content = "(Naroxel segura minhas mãos e sinto que as mãos dela estão frias.)",
  ui_story_5057_50570302_66_dialog_content = "Pelo futuro dos Celestitas e Eraveil.",
  ui_story_5057_50570302_67_dialog_content = "<color=#e8d9bb>Então nós andamos na roda-gigante juntos, Naroxel e eu, e apreciamos a vista noturna do Denuo Valley Resort.</color>",
  ui_story_5057_50570401_1_dialog_content = "Onde está o convidado? Falta apenas um minuto para a hora que combinamos de nos encontrar...",
  ui_story_5057_50570401_2_dialog_content = "PlayerName...?",
  ui_story_5057_50570401_3_dialog_content = "Essa voz... Michenny?",
  ui_story_5057_50570401_4_dialog_content = "Você não seria o guia, seria, PlayerName?",
  ui_story_5057_50570401_5_dialog_content = "Eu sou! Você é o convidado, entendi. Não é à toa que você está pontual.",
  ui_story_5057_50570401_6_dialog_content = "Fico lisonjeado. A propósito, como é que você está trabalhando como guia aqui?",
  ui_story_5057_50570401_7_dialog_content = "Pois é... É exatamente o que parece, eu arrumei um emprego...",
  ui_story_5057_50570401_8_dialog_content = "Um emprego? Entendi, é quando você troca seu tempo por dinheiro.",
  ui_story_5057_50570401_9_dialog_content = "Sim, essa é uma descrição muito precisa!",
  ui_story_5057_50570401_10_dialog_content = "Tudo bem, acho que vou deixar você liderar o caminho então, PlayerName.",
  ui_story_5057_50570401_11_dialog_content = "Sim, deixe comigo!",
  ui_story_5057_50570401_12_dialog_content = "Céu Azul, Matriz Fantasia, Dragão da Noite Clara, Tiros de Halo... Nós experimentamos todos.",
  ui_story_5057_50570401_13_dialog_content = "Tudo graças a você, PlayerName. Provavelmente não conseguiria experimentar tantos assim sozinho.",
  ui_story_5057_50570401_14_dialog_content = "Aqui, tome uma bebida. Acabei de esfriá-la com Luminática.",
  ui_story_5057_50570401_15_dialog_content = "Obrigada!",
  ui_story_5057_50570401_16_dialog_content = "Glub, glub...",
  ui_story_5057_50570401_17_dialog_content = "Ah—! É muito melhor quando está frio.",
  ui_story_5057_50570401_18_dialog_content = "Afinal, o objetivo de ir ao parque é se divertir.",
  ui_story_5057_50570401_19_dialog_content = "Também me deixa feliz ver você deixar o decoro de lado pelo puro prazer.",
  ui_story_5057_50570401_20_dialog_content = "Estou muito feliz, de fato.",
  ui_story_5057_50570401_21_dialog_content = "É muito divertido aqui, com muitas novidades.",
  ui_story_5057_50570401_22_dialog_content = "Ah, o que é isso, PlayerName?",
  ui_story_5057_50570401_23_dialog_content = "É uma máquina de garra!",
  ui_story_5057_50570401_24_dialog_content = "Máquina de garra? Não entendi.",
  ui_story_5057_50570401_25_dialog_content = "Permita-me demonstrar.",
  ui_story_5057_50570401_26_dialog_content = "Primeiro, insira algumas moedas.",
  ui_story_5057_50570401_27_dialog_content = "Por favor, me dê um minuto... São cinco moedas, não é?",
  ui_story_5057_50570401_28_dialog_content = "Sim. Ele quer cinco Noitium porque este tem melhores prêmios.",
  ui_story_5057_50570401_29_dialog_content = "Após inserir as moedas, use o bastão para posicionar a garra para pegar.",
  ui_story_5057_50570401_30_dialog_content = "Agora escolha algo que você goste!",
  ui_story_5057_50570401_31_dialog_content = "Beleza!",
  ui_story_5057_50570401_32_dialog_content = "Mova a garra sobre o objeto com o bastão.",
  ui_story_5057_50570401_33_dialog_content = "Olhe de todas as direções para descobrir o ângulo e mire a garra nele.",
  ui_story_5057_50570401_34_dialog_content = "Então aperte o botão!",
  ui_story_5057_50570401_35_dialog_content = "Uau, está descendo.",
  ui_story_5057_50570401_36_dialog_content = "Está em suas mãos!",
  ui_story_5057_50570401_37_dialog_content = "Uhum. Agora espere a garra pegar e soltar o prêmio na caixa.",
  ui_story_5057_50570401_38_dialog_content = "Estou tão nervoso...",
  ui_story_5057_50570401_39_dialog_content = "Ah!",
  ui_story_5057_50570401_40_dialog_content = "A garra girou logo antes de soltar.",
  ui_story_5057_50570401_41_dialog_content = "Isso acontece às vezes. É mais frequente você não conseguir um prêmio.",
  ui_story_5057_50570401_42_dialog_content = "Então, o que acontece com as moedas quando você falha?",
  ui_story_5057_50570401_43_dialog_content = "Ah, você gastou e eles se foram?",
  ui_story_5057_50570401_44_dialog_content = "O quê?!",
  ui_story_5057_50570401_45_dialog_content = "P-Por quê?",
  ui_story_5057_50570401_46_dialog_content = "Eu não ganhei um prêmio. Isso não significa que tenho direito a um reembolso?",
  ui_story_5057_50570401_47_dialog_content = "Hmm, como devo explicar isso...",
  ui_story_5057_50570401_48_dialog_content = "Você obviamente investiu esforço e dinheiro, mas não obteve retorno com isso.",
  ui_story_5057_50570401_49_dialog_content = "Com base no tempo gasto, vale pelo menos cinquenta Noitium.",
  ui_story_5057_50570401_50_dialog_content = "Sério? Acho que o tempo vale apenas dez Noitium, até onde eu sei.",
  ui_story_5057_50570401_51_dialog_content = "Não é a mesma coisa hoje!",
  ui_story_5057_50570401_52_dialog_content = "Tá bom...",
  ui_story_5057_50570401_53_option_content = "É porque está de férias hoje?",
  ui_story_5057_50570401_54_dialog_content = "Sim! Trabalhar em feriados paga cinco vezes a taxa normal!",
  ui_story_5057_50570401_55_option_content = "É porque estou trabalhando como guia?",
  ui_story_5057_50570401_56_dialog_content = "Sim. Como meu guia, você vale muito mais.",
  ui_story_5057_50570401_57_dialog_content = "Sem falar que acho que você é um excelente guia e merece um bônus.",
  ui_story_5057_50570401_58_dialog_content = "Sério? Estou bem, desde que você esteja se divertindo!",
  ui_story_5057_50570401_59_dialog_content = "Além disso, o esforço que você colocou deve exigir mais cinquenta Noitium!",
  ui_story_5057_50570401_60_dialog_content = "Juntos, isso faz cento e cinco Noitium, ou duzentos e cinco para duas pessoas!",
  ui_story_5057_50570401_61_dialog_content = "E-Espere, Michenny!",
  ui_story_5057_50570401_62_dialog_content = "Isso é apenas um jogo. Você não pode olhar para isso da mesma forma.",
  ui_story_5057_50570401_63_dialog_content = "Hã?",
  ui_story_5057_50570401_64_dialog_content = "Deixe-me colocar desta forma, estamos gastando dinheiro pela experiência, não pelo resultado.",
  ui_story_5057_50570401_65_dialog_content = "O importante aqui é aproveitar o processo divertido com os amigos.",
  ui_story_5057_50570401_66_dialog_content = "Isso também vale para este jogo. Gastei as moedas porque queria que você se divertisse com a máquina.",
  ui_story_5057_50570401_67_dialog_content = "Foi interessante...",
  ui_story_5057_50570401_68_dialog_content = "A probabilidade de ganhar um prêmio é baixa, então eu não estava esperando nada.",
  ui_story_5057_50570401_69_dialog_content = "Entendo...",
  ui_story_5057_50570401_70_dialog_content = "(Acho que o Michenny está começando a entender.)",
  ui_story_5057_50570401_71_dialog_content = "Gastando dinheiro para obter experiência...",
  ui_story_5057_50570401_72_dialog_content = "Certo.",
  ui_story_5057_50570401_73_dialog_content = "E a recompensa emocional disso...",
  ui_story_5057_50570401_74_dialog_content = "Correto!",
  ui_story_5057_50570401_75_dialog_content = "Com a chance de ganhar um prêmio...",
  ui_story_5057_50570401_76_dialog_content = "Sim, é exatamente isso!",
  ui_story_5057_50570401_77_dialog_content = "Isso...",
  ui_story_5057_50570401_78_dialog_content = "Apostas!",
  ui_story_5057_50570401_79_dialog_content = "Devo auditar você de acordo com as regulamentações de Lumópolis!",
  ui_story_5057_50570401_80_dialog_content = "C-Calma, pare de forçar a abertura da fenda da moeda!",
  ui_story_5057_50570401_81_dialog_content = "<color=#e8d9bb>Então eu dou tudo de mim para convencer Michenny e levá-la para ganhar um monte de bonecas na máquina de garra.</color>",
  ui_story_5057_50570402_1_dialog_content = "Aham...",
  ui_story_5057_50570402_2_dialog_content = "Bom Dia, PlayerName.",
  ui_story_5057_50570402_3_dialog_content = "Bom dia, Michenny.",
  ui_story_5057_50570402_4_dialog_content = "Ah, desculpe por perder a calma da última vez.",
  ui_story_5057_50570402_5_dialog_content = "Hã? Ah, você quer dizer com a máquina de garra?",
  ui_story_5057_50570402_6_dialog_content = "Eu não acho que você perdeu a calma.",
  ui_story_5057_50570402_7_option_content = "Achei bem fofo.",
  ui_story_5057_50570402_8_dialog_content = "Já que você é sempre tão sério...",
  ui_story_5057_50570402_9_dialog_content = "Eu chamaria isso de ver um lado mais pé no chão seu, e é uma grande diferença.",
  ui_story_5057_50570402_10_dialog_content = "Aham... Você acha?",
  ui_story_5057_50570402_11_option_content = "Todo mundo se emociona de vez em quando.",
  ui_story_5057_50570402_12_dialog_content = "Tenho certeza de que isso também acontece com você às vezes, Michenny.",
  ui_story_5057_50570402_13_dialog_content = "Desculpe por ter que presenciar isso.",
  ui_story_5057_50570402_14_dialog_content = "Você seria meu guia novamente hoje, PlayerName?",
  ui_story_5057_50570402_15_dialog_content = "Ficarei feliz em fazer isso!",
  ui_story_5057_50570402_16_dialog_content = "Ufa, gastou-se muito na loja de souvenires.",
  ui_story_5057_50570402_17_dialog_content = "É assustador quantas coisas Michenny comprou...",
  ui_story_5057_50570402_18_dialog_content = "Você acha que é assustador?",
  ui_story_5057_50570402_19_dialog_content = "Você não acha esse lagarto de pelúcia do deserto fofo?",
  ui_story_5057_50570402_20_dialog_content = "E esta caixa tem doces de todos os sabores bizarros do mundo... Preciso comprar em grande quantidade para compartilhar com colegas e amigos em casa.",
  ui_story_5057_50570402_21_dialog_content = "Então temos a moeda comemorativa. Ela não é uma moeda legal, mas a imagem nela é muito agradável.",
  ui_story_5057_50570402_22_dialog_content = "Isso vai me lembrar da diversão que tive com PlayerName aqui quando eu olhar para isso.",
  ui_story_5057_50570402_23_dialog_content = "Esta moeda tem um valor muito superior ao de uma moeda comum.",
  ui_story_5057_50570402_24_dialog_content = "Não foi essa a lição que você me ensinou, PlayerName?",
  ui_story_5057_50570402_25_dialog_content = "Ah, sim, eu acho.",
  ui_story_5057_50570402_26_dialog_content = "Afinal, você está em uma rara férias, então deve gastar dinheiro no que quer e gosta.",
  ui_story_5057_50570402_27_dialog_content = "É difícil gastar dinheiro, de qualquer forma, quando você está ocupado demais trabalhando o tempo todo.",
  ui_story_5057_50570402_28_dialog_content = "Viva a vida ao máximo, ou seja, quando o momento é certo, o dinheiro gasto tem um significado muito maior do que o normal.",
  ui_story_5057_50570402_29_dialog_content = "Acredito que foi isso que você me ensinou da última vez.",
  ui_story_5057_50570402_30_dialog_content = "Uau, você aprende rápido, Michenny.",
  ui_story_5057_50570402_31_dialog_content = "Então, por que você parece surpreso?",
  ui_story_5057_50570402_32_dialog_content = "Porque não parecia algo que você diria normalmente, acho que estou vendo outro lado de Michenny!",
  ui_story_5057_50570402_33_dialog_content = "Claro, a multifacetada natureza das pessoas é o motivo pelo qual é difícil medi-las pelo dinheiro.",
  ui_story_5057_50570402_34_dialog_content = "Ter emoções variadas e diferentes aparências também é valioso, em certo sentido.",
  ui_story_5057_50570402_35_dialog_content = "Quanto a você ver outro lado de mim, vou levar isso como um elogio.",
  ui_story_5057_50570402_36_dialog_content = "Claro que é!",
  ui_story_5057_50570402_37_dialog_content = "Ufa, estou em um ânimo muito melhor depois das compras...",
  ui_story_5057_50570402_38_dialog_content = "Ei, qual é aquele prédio ali? Eu não acho que estivemos lá ainda.",
  ui_story_5057_50570402_39_dialog_content = "Ah, essa é uma atração que ainda não está aberta ao público, mas acho que eles estão testando agora.",
  ui_story_5057_50570402_40_dialog_content = "Hmm...",
  ui_story_5057_50570402_41_dialog_content = "Vamos conferir. Uma experiência completa será cem Noitium mais valiosa do que uma memória de partir com arrependimento.",
  ui_story_5057_50570402_42_dialog_content = "Hã? Espere, Michenny!",
  ui_story_5057_50570402_43_dialog_content = "Pare de correr! É perigoso visitar atrações não inauguradas!",
  ui_story_5057_50570402_44_dialog_content = "Ei, por que a porta não pode ser aberta?",
  ui_story_5057_50570402_45_dialog_content = "Não seria perfeito? É difícil ter todo o espaço só para você.",
  ui_story_5057_50570402_46_dialog_content = "Sem chance! Eu também não consigo entender nada... Como vamos aproveitar isso?",
  ui_story_5057_50570402_47_dialog_content = "*soluço*...",
  ui_story_5057_50570402_48_dialog_content = "Espere, ouvi algo...",
  ui_story_5057_50570402_49_dialog_content = "O grito assustador... Será Eclipsita?",
  ui_story_5057_50570402_50_dialog_content = "Não, eu não sinto o Darkflow em lugar algum aqui!",
  ui_story_5057_50570402_51_dialog_content = "Será que isso pode ser... *engole em seco*",
  ui_story_5057_50570402_52_dialog_content = "O que te fez engolir em seco, PlayerName...",
  ui_story_5057_50570402_53_dialog_content = "Eu me lembro agora. Entre os passeios inacabados está uma casa mal-assombrada chamada Frenesi Fantasma.",
  ui_story_5057_50570402_54_dialog_content = "Cheio de coisas aterrorizantes dentro...",
  ui_story_5057_50570402_55_dialog_content = "O-O quê? Isso não pode ser... É infantil...",
  ui_story_5057_50570402_56_dialog_content = "Argh...!",
  ui_story_5057_50570402_57_dialog_content = "Eeee!",
  ui_story_5057_50570402_58_dialog_content = "S-Pare de me empurrar, Michenny!",
  ui_story_5057_50570402_59_dialog_content = "Abra a porta, abra agora!",
  ui_story_5057_50570402_60_dialog_content = "Devolva... Devolva meu Lumâmbar, agora!!!",
  ui_story_5057_50570402_61_dialog_content = "!!!",
  ui_story_5057_50570402_62_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5057_50570402_63_dialog_content = "M-Michenny...?",
  ui_story_5057_50570402_64_dialog_content = "Então, não era Lorelei?",
  ui_story_5057_50570402_65_dialog_content = "<color=#e8d9bb>Então, para acalmar a Michenny, eu a levo para jantar e faço um grande esforço explicando como funciona a casa mal-assombrada.</color>",
  ui_story_5057_50570501_1_dialog_content = "Florine...",
  ui_story_5057_50570501_2_dialog_content = "Ah, aí está você.",
  ui_story_5057_50570501_3_dialog_content = "Arf, arf... desculpe mantê-lo esperando.",
  ui_story_5057_50570501_4_dialog_content = "Tudo bem. Eu também não estou aqui há muito tempo.",
  ui_story_5057_50570501_5_dialog_content = "Como cavaleiro da divisão, tenho paciência.",
  ui_story_5057_50570501_6_dialog_content = "Bom saber que estou atrasado de forma aceitável.",
  ui_story_5057_50570501_7_dialog_content = "Após receber sua mensagem, troquei para um traje de banho e corri imediatamente.",
  ui_story_5057_50570501_8_dialog_content = "Hmm...",
  ui_story_5057_50570501_9_dialog_content = "(Algo sobre Florine hoje...)",
  ui_story_5057_50570501_10_dialog_content = "(É porque ela está de maiô?)",
  ui_story_5057_50570501_11_dialog_content = "Já viu o suficiente, PlayerName?",
  ui_story_5057_50570501_12_dialog_content = "Ops, pegos.",
  ui_story_5057_50570501_13_dialog_content = "Parece que estou sob a luz de uma lâmpada de um milhão de watts.",
  ui_story_5057_50570501_14_dialog_content = "Desculpe, não quis encarar você dessa maneira!",
  ui_story_5057_50570501_15_dialog_content = "Ah, bem, eu acho que você está especialmente adorável hoje, não consigo evitar querer descobrir o que te faz diferente.",
  ui_story_5057_50570501_16_dialog_content = "É uma desculpa bem fraca, mas eu aceito.",
  ui_story_5057_50570501_17_dialog_content = "Aliás, você também ficou olhando a última vez que eu estava de maiô.",
  ui_story_5057_50570501_18_dialog_content = "EveEmbora não seja suficiente para me deixar bravo... ou feliz.",
  ui_story_5057_50570501_19_dialog_content = "Você precisa se concentrar na missão que estamos prestes a realizar.",
  ui_story_5057_50570501_20_dialog_content = "Sim! Estou feliz que você não está bravo, Florine.",
  ui_story_5057_50570501_21_dialog_content = "Ah, você mencionou uma missão para hoje?",
  ui_story_5057_50570501_22_dialog_content = "Vamos discutir isso conforme avançamos.",
  ui_story_5057_50570501_23_dialog_content = "Claro que não!",
  ui_story_5057_50570501_24_dialog_content = "Estou animado com a missão. Me diga o que é.",
  ui_story_5057_50570501_25_dialog_content = "E é uma honra trabalhar ao lado de Florine!",
  ui_story_5057_50570501_26_dialog_content = "Uh, como você está tão animado?",
  ui_story_5057_50570501_27_dialog_content = "Eu poderia chamar isso de missão, mas na verdade não é nada especial.",
  ui_story_5057_50570501_28_dialog_content = "É muito fácil, na verdade, e isso é passar o dia de folga relaxando no resort.",
  ui_story_5057_50570501_29_dialog_content = "O quê? Isso também conta como uma missão?",
  ui_story_5057_50570501_30_dialog_content = "Claro, e preciso escrever um relatório sobre isso hoje à noite.",
  ui_story_5057_50570501_31_dialog_content = "Eu não preciso entregar, mas é necessário resumir o dia de folga.",
  ui_story_5057_50570501_32_dialog_content = "Tá bom. Devemos ir à areia ou nadar? Mayser uma caminhada ou pescaria?",
  ui_story_5057_50570501_33_dialog_content = "Se houver conchas, podemos ver quem encontra a maior!",
  ui_story_5057_50570501_34_dialog_content = "Ah, eu não tenho planos específicos, então veremos quando chegarmos lá.",
  ui_story_5057_50570501_35_dialog_content = "No entanto, você parece muito entusiasmado.",
  ui_story_5057_50570501_36_dialog_content = "Isso ocorre porque coisas interessantes tendem a acontecer quando um cavaleiro da Divisão de Investigação de Hereges está de férias comigo.",
  ui_story_5057_50570501_37_dialog_content = "Tudo bem, nada interessante vai acontecer nessas férias.",
  ui_story_5057_50570501_38_dialog_content = "Eu tenho um forte pressentimento!",
  ui_story_5057_50570501_39_dialog_content = "Sentindo? Como se algo interessante estivesse prestes a acontecer?",
  ui_story_5057_50570501_40_dialog_content = "Sim!",
  ui_story_5057_50570501_41_dialog_content = "É interessante apenas estar com Florine!",
  ui_story_5057_50570501_42_dialog_content = "Agora, isso está indo longe demais...",
  ui_story_5057_50570501_43_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5057_50570501_44_dialog_content = "Ops, desculpe.",
  ui_story_5057_50570501_45_dialog_content = "Eu tô bem. Você não está ferido, está?",
  ui_story_5057_50570501_46_dialog_content = "Estou bem, valeu! Você é um cara tão gentil e bonito.",
  ui_story_5057_50570501_47_dialog_content = "...",
  ui_story_5057_50570501_48_dialog_content = "Isso foi descuidado, quase me derrubou...",
  ui_story_5057_50570501_49_dialog_content = "...",
  ui_story_5057_50570501_50_dialog_content = "Ah?",
  ui_story_5057_50570501_51_dialog_content = "(F-Florine tem aquele olhar assustador nos olhos dela.)",
  ui_story_5057_50570501_52_dialog_content = "Seu maiô está frouxo, PlayerName.",
  ui_story_5057_50570501_53_dialog_content = "Não se mexa e deixe-me ajudar.",
  ui_story_5057_50570501_54_dialog_content = "O quê? Ei?!",
  ui_story_5057_50570501_55_dialog_content = "Não tão difícil, Florine!",
  ui_story_5057_50570501_56_dialog_content = "Você está me sufocando!",
  ui_story_5057_50570501_57_dialog_content = "Tome uma bebida, por favor.",
  ui_story_5057_50570501_58_dialog_content = "Glub, glub...",
  ui_story_5057_50570501_59_dialog_content = "Uh, sobre o que acabou de acontecer, me desculpe. Admitem que perdi o foco na missão.",
  ui_story_5057_50570501_60_dialog_content = "Tudo bem, você está perdoado.",
  ui_story_5057_50570501_61_dialog_content = "Embora você não precise se desculpar por isso. Você é livre para fazer o que quiser... desde que não afete o progresso da tarefa.",
  ui_story_5057_50570501_62_dialog_content = "Oh... Desculpe. Então, o que fez você decidir pescar?",
  ui_story_5057_50570501_63_dialog_content = "Porque é muito tranquilo e a vista é agradável.",
  ui_story_5057_50570501_64_dialog_content = "Também não é tão intenso quanto os passeios. Você não acha bom relaxar e conversar livremente também?",
  ui_story_5057_50570501_65_dialog_content = "Você parece cansado de todos os recados também... Isso deve te dar mais tempo para relaxar.",
  ui_story_5057_50570501_66_dialog_content = "Verdade, eu tenho perdido a cabeça ultimamente... Você é muito atencioso, Florine.",
  ui_story_5057_50570501_67_dialog_content = "...",
  ui_story_5057_50570501_68_dialog_content = "No entanto, ainda não peguei nenhum peixe.",
  ui_story_5057_50570501_69_dialog_content = "Será que eu os assustei?",
  ui_story_5057_50570501_70_dialog_content = "Gostaria de tentar, o gentil e belo Sr. Celestita?",
  ui_story_5057_50570501_71_dialog_content = "Eu? Sinceramente, sou muito bom quando se trata de pescaria.",
  ui_story_5057_50570501_72_dialog_content = "Então, deixe-me tentar!",
  ui_story_5057_50570501_73_dialog_content = "Tudo bem, relaxe e respire...",
  ui_story_5057_50570501_74_dialog_content = "(Florine tem estado fixado em mim todo esse tempo.)",
  ui_story_5057_50570501_75_dialog_content = "Uh, você não deveria estar olhando para a água, Florine?",
  ui_story_5057_50570501_76_dialog_content = "Shhh, quero estudar sua pose de pescaria.",
  ui_story_5057_50570501_77_dialog_content = "É mesmo? Tá bom.",
  ui_story_5057_50570501_78_dialog_content = "...!",
  ui_story_5057_50570501_79_dialog_content = "Eu levei uma mordida! Uma bem forte também!",
  ui_story_5057_50570501_80_dialog_content = "Eu-Eu não consigo puxar. Está me arrastando para baixo!",
  ui_story_5057_50570501_81_dialog_content = "Deixe pra lá, PlayerName!",
  ui_story_5057_50570501_82_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5057_50570501_83_dialog_content = "(Oh, o que aconteceu...? Acho que fui arrastado para a água por um peixe grande...)",
  ui_story_5057_50570501_84_dialog_content = "(O que é essa coisa macia debaixo da minha cabeça...?)",
  ui_story_5057_50570501_85_dialog_content = "Hmm... espera, será que é... Florine?",
  ui_story_5057_50570501_86_dialog_content = "Claro que sou eu, PlayerName.",
  ui_story_5057_50570501_87_dialog_content = "Você se importa de parar de fazer bagunça? Eu deveria ter usado um cacto como seu travesseiro...",
  ui_story_5057_50570501_88_dialog_content = "D-Desculpe! Vou me levantar agora mesmo!",
  ui_story_5057_50570501_89_dialog_content = "<color=#e8d9bb>Então, em uma atmosfera bastante sutil, janto com Florine. Ela está brava ou o quê...?</color>",
  ui_story_5057_50570502_1_dialog_content = "Obrigado pelo que você fez, Florine.",
  ui_story_5057_50570502_2_dialog_content = "Hã?",
  ui_story_5057_50570502_3_dialog_content = "Você acabou de salvar minha vida.",
  ui_story_5057_50570502_4_dialog_content = "Eu ia pegar o peixe, grelhar ou fazer uma panela quente de Longzhou que aprendi da última vez para tratá-lo.",
  ui_story_5057_50570502_5_dialog_content = "Eu não esperava que fosse tão forte...",
  ui_story_5057_50570502_6_dialog_content = "De nada.",
  ui_story_5057_50570502_7_dialog_content = "Mas esqueça essa ideia. Aquele peixe era grande o suficiente para engolir nós dois.",
  ui_story_5057_50570502_8_dialog_content = "Hã?",
  ui_story_5057_50570502_9_dialog_content = "(Por que há um peixe tão perigoso aqui?)",
  ui_story_5057_50570502_10_dialog_content = "Felizmente, eu escolhi primeiros socorros como matéria eletiva no meu segundo semestre na Dawn Academia.",
  ui_story_5057_50570502_11_dialog_content = "Ahem, embora quase ninguém tenha escolhido o curso e tenha sido completamente esquecido.",
  ui_story_5057_50570502_X11_dialog_content = "Acredito que qualquer conhecimento que salva vidas é precioso.",
  ui_story_5057_50570502_12_dialog_content = "Eu orei para que nunca precisasse usar o conhecimento, apenas para PlayerName ser a primeira vítima afogada que eu salvei.",
  ui_story_5057_50570502_13_dialog_content = "Salvando vítimas afogadas... Eu me lembro que o Soroz me ensinou isso.",
  ui_story_5057_50570502_14_dialog_content = "PlayerName, você ainda se lembra de como resgatar alguém que está se afogando?",
  ui_story_5057_50570502_15_dialog_content = "Primeiro, você precisa tirar a pessoa afogada da água.",
  ui_story_5057_50570502_16_dialog_content = "Então, verifique se eles ainda estão respirando e têm pulso.",
  ui_story_5057_50570502_17_dialog_content = "Se não, execute imediatamente medidas como compressões torácicas e respiração de resgate até que recuperem a consciência ou a assistência profissional chegue.",
  ui_story_5057_50570502_18_dialog_content = "Além disso, mantenha a cabeça da pessoa mais baixa que o corpo para evitar que o vômito entre nas vias respiratórias.",
  ui_story_5057_50570502_19_dialog_content = "De novo, Soroz? Não importa quantas vezes você me ensine, eu não vou ter a chance de usar isso...",
  ui_story_5057_50570502_20_dialog_content = "Mantenha o ânimo, PlayerName. Eu realmente espero que você nunca precise usar essas coisas.",
  ui_story_5057_50570502_21_dialog_content = "Mas se um incidente inesperado acontecer, espero que você possa salvar alguém querido com esse conhecimento.",
  ui_story_5057_50570502_22_dialog_content = "Hmm, deixa eu pensar...",
  ui_story_5057_50570502_23_dialog_content = "Eu estava deitado em suas pernas, não é?",
  ui_story_5057_50570502_24_dialog_content = "Sim, porque você estava respirando novamente.",
  ui_story_5057_50570502_25_dialog_content = "Respirando de novo? Isso significa que eu parei de respirar...",
  ui_story_5057_50570502_26_option_content = "Então você deve ter...!",
  ui_story_5057_50570502_27_dialog_content = "É apenas um procedimento médico normal, não precisa gritar!",
  ui_story_5057_50570502_28_dialog_content = "Eu só fiz isso porque você caiu acidentalmente na água...",
  ui_story_5057_50570502_29_dialog_content = "A-E você acordou logo depois que fiz as compressões torácicas.",
  ui_story_5057_50570502_30_dialog_content = "Oh, eu vejo...",
  ui_story_5057_50570502_31_option_content = "Então, basicamente, voltei a respirar por mim mesmo!",
  ui_story_5057_50570502_32_dialog_content = "Uhum. Vai saber, talvez você seja na verdade um peixe.",
  ui_story_5057_50570502_33_dialog_content = "Desculpe, tudo que eu conseguia pensar naquele momento era qual prato fazer...",
  ui_story_5057_50570502_34_dialog_content = "Sem falar que me sinto estranhamente seguro sempre que estou com você, Florine.",
  ui_story_5057_50570502_35_dialog_content = "... Deixe pra lá. É bom que você esteja bem. Difícil o suficiente cuidar de você o tempo todo.",
  ui_story_5057_50570502_36_dialog_content = "Não, não dá para esquecer!",
  ui_story_5057_50570502_37_dialog_content = "Eu preciso te reembolsar pela dívida!",
  ui_story_5057_50570502_38_dialog_content = "O-O que você tá fazendo...?",
  ui_story_5057_50570502_39_dialog_content = "Eu sei que você está agradecido, PlayerName, mas isso é demais.",
  ui_story_5057_50570502_40_dialog_content = "Isso vai custar cada centavo do seu salário!",
  ui_story_5057_50570502_41_dialog_content = "Não, não é demais para o meu salvador! Eu sempre posso recuperar meu salário!",
  ui_story_5057_50570502_42_dialog_content = "Deixe-me ver, então aqui compramos o Marshmallow Stardust, sorvete sabor lagarto e suco de menta com cacto.",
  ui_story_5057_50570502_43_dialog_content = "Além da bebida do canyon cachoeira e a Salsicha Galáxia.",
  ui_story_5057_50570502_44_dialog_content = "Correto, e ambos os meus braços estão cheios.",
  ui_story_5057_50570502_45_dialog_content = "Isso deve ser suficiente, não é?",
  ui_story_5057_50570502_46_dialog_content = "Ah, eu não acho que seja suficiente ainda.",
  ui_story_5057_50570502_47_dialog_content = "Confira, o único espinheiro cristalizado de Longzhou em todo o deserto de Rediesel!",
  ui_story_5057_50570502_48_dialog_content = "Acabei de cobri-los com calda fresquinha. Experimente e você nunca se arrependerá!",
  ui_story_5057_50570502_49_dialog_content = "Me dê um, por favor!",
  ui_story_5057_50570502_50_dialog_content = "Esta é a primeira vez que vejo este lanche de Longzhou. De uma chance, Florine!",
  ui_story_5057_50570502_51_dialog_content = "Eu gostaria muito, mas estou com metade da comida desta rua nos meus braços agora...",
  ui_story_5057_50570502_52_dialog_content = "Verdadeiro... Ei, que tal eu te alimentar?",
  ui_story_5057_50570502_53_dialog_content = "O quê? N-Não, isso não está certo. Eu recuso.",
  ui_story_5057_50570502_54_dialog_content = "Vamos lá, dê uma mordida... Ops, a cobertura de açúcar está caindo!",
  ui_story_5057_50570502_55_dialog_content = "Ah, sério?",
  ui_story_5057_50570502_56_dialog_content = "<color=#e8d9bb>Florine morde rapidamente a fruta mais abaixo, sua superfície vermelha vibrante pingando com xarope doce.</color>",
  ui_story_5057_50570502_57_dialog_content = "Acho que está tudo bem.",
  ui_story_5057_50570502_58_dialog_content = "Oh! Como eu invejo vocês, jovens, por poderem se divertir na estrada assim.",
  ui_story_5057_50570502_59_dialog_content = "...!",
  ui_story_5057_50570502_60_dialog_content = "Fizemos algo errado?",
  ui_story_5057_50570502_61_dialog_content = "Por que seu rosto está tão vermelho, Florine? A sua comida faz o rosto das pessoas ficarem vermelhos, senhor?",
  ui_story_5057_50570502_62_dialog_content = "PlayerName！",
  ui_story_5057_50570502_63_dialog_content = "Estou aqui! O que foi?",
  ui_story_5057_50570502_64_dialog_content = "Abra. A batata assada também é muito boa.",
  ui_story_5057_50570502_65_dialog_content = "Só me entregue... Ah!",
  ui_story_5057_50570502_66_dialog_content = "<color=#e8d9bb>Florine, todo envergonhado, enfia uma batata assada diretamente na minha boca.</color>",
  ui_story_5057_50570502_67_dialog_content = "Vocês têm uma conexão tão boa! Aqui, deixe-me pegar outra tigela para vocês de graça!",
  ui_story_5057_50570502_68_dialog_content = "<color=#e8d9bb>Depois, Florine insiste em dividir as despesas comigo. Isso é tão... Florine.</color>",
  ui_story_5057_50570601_1_dialog_content = "E-Eu estou nervoso.",
  ui_story_5057_50570601_2_dialog_content = "Claro, sou amigo de Sua Majestade Bethlehem...",
  ui_story_5057_50570601_3_dialog_content = "Mas ainda fico ansioso ao encontrar com ela sozinho, por alguma razão...",
  ui_story_5057_50570601_4_dialog_content = "Sem mencionar que estou representando o resort em nome de Lorelei...",
  ui_story_5057_50570601_5_dialog_content = "Estou apresentável, certo...? Ah, eu estava usando isso o tempo todo.",
  ui_story_5057_50570601_6_dialog_content = "Então eu provavelmente não vou envergonhar os Celestitas... Espero que não...",
  ui_story_5057_50570601_7_dialog_content = "E, esperamos que também não seja um constrangimento para o resort.",
  ui_story_5057_50570601_8_dialog_content = "PlayerName...",
  ui_story_5057_50570601_9_dialog_content = "Lorelei não descontaria meu salário, descontaria?",
  ui_story_5057_50570601_10_dialog_content = "PlayerName?",
  ui_story_5057_50570601_11_dialog_content = "S-Sim!",
  ui_story_5057_50570601_12_dialog_content = "Vossa Majestade!",
  ui_story_5057_50570601_13_dialog_content = "Não estou interrompendo nada, estou?",
  ui_story_5057_50570601_14_dialog_content = "Você parece preocupado?",
  ui_story_5057_50570601_15_dialog_content = "Não, não, de forma alguma! Ser seu anfitrião é sempre um prazer, Vossa Majestade.",
  ui_story_5057_50570601_16_dialog_content = "Lorelei tem se culpado por não ter te entretido antes, pois estava ocupada com Eclipsitas.",
  ui_story_5057_50570601_17_dialog_content = "E eu espero que você aproveite bem estas raras férias no resort.",
  ui_story_5057_50570601_18_dialog_content = "Imagino que os assuntos do tribunal provavelmente te cansaram.",
  ui_story_5057_50570601_19_dialog_content = "Entendi. Eu agradeço.",
  ui_story_5057_50570601_20_dialog_content = "Hahaha, não importa quantas vezes eu monte o Dragão da Noite Clara, ainda é emocionante.",
  ui_story_5057_50570601_21_dialog_content = "Minhas pernas ainda estão tremendo agora...",
  ui_story_5057_50570601_22_dialog_content = "Mas você parece calmo e controlado, Vossa Majestade.",
  ui_story_5057_50570601_23_dialog_content = "De fato, já que estou acostumado a cavalgar um dragão voador.",
  ui_story_5057_50570601_24_dialog_content = "Você realmente vivenciou tudo, Vossa Majestade.",
  ui_story_5057_50570601_25_dialog_content = "Chá e lanche para você.",
  ui_story_5057_50570601_26_dialog_content = "Obrigada, PlayerName.",
  ui_story_5057_50570601_27_dialog_content = "Onde está sua porção?",
  ui_story_5057_50570601_28_dialog_content = "Ah, o Lorelei pediu ao chef para preparar isso especialmente para você.",
  ui_story_5057_50570601_29_dialog_content = "Ouvi dizer que ele usou muitos ingredientes preciosos e caros.",
  ui_story_5057_50570601_30_dialog_content = "É mesmo?",
  ui_story_5057_50570601_31_dialog_content = "(Hmm, acho que Queen Bethlehem não está de muito bom ânimo.)",
  ui_story_5057_50570601_32_dialog_content = "PlayerName.",
  ui_story_5057_50570601_33_dialog_content = "Muito bem, Vossa Majestade!",
  ui_story_5057_50570601_34_dialog_content = "Eu tenho uma pergunta.",
  ui_story_5057_50570601_35_dialog_content = "Por favor, pergunte.",
  ui_story_5057_50570601_36_dialog_content = "Em qual papel você está me acompanhando, PlayerName?",
  ui_story_5057_50570601_37_option_content = "Uh, anfitrião do resort?",
  ui_story_5057_50570601_38_dialog_content = "Eu recebo um salário da Lorelei depois de tudo...",
  ui_story_5057_50570601_39_option_content = "Uh, um amigo próximo de Sua Majestade?",
  ui_story_5057_50570601_40_dialog_content = "Bem, isso provavelmente é um exagero.",
  ui_story_5057_50570601_41_dialog_content = "Mas eu acho que posso lidar com o trabalho, não é?",
  ui_story_5057_50570601_42_dialog_content = "Eu não acho que isso vai me deixar completamente tranquilo.",
  ui_story_5057_50570601_43_dialog_content = "Obrigado pelo destino, nos conhecemos há bastante tempo, mas você ainda parece preso à minha posição.",
  ui_story_5057_50570601_44_dialog_content = "Mas você é o Queen do Norte... Eu preferiria não ofendê-lo sendo muito informal.",
  ui_story_5057_50570601_45_dialog_content = "Não, você não está me ofendendo.",
  ui_story_5057_50570601_46_dialog_content = "Eu só sinto que a vibe agora está colocando um espaço entre nós.",
  ui_story_5057_50570601_47_dialog_content = "Sua atitude está me fazendo sentir como se estivesse em uma função oficial.",
  ui_story_5057_50570601_48_dialog_content = "Desculpe...",
  ui_story_5057_50570601_49_dialog_content = "Por favor, não abaixe a cabeça, Celestita. Você ainda se lembra que é o escolhido?",
  ui_story_5057_50570601_50_dialog_content = "Claro que eu faço!",
  ui_story_5057_50570601_51_dialog_content = "Se você realmente quer me ajudar a aliviar o estresse...",
  ui_story_5057_50570601_52_dialog_content = "Então me ajude a esquecer meu status de rainha e pular esses protocolos formais.",
  ui_story_5057_50570601_53_dialog_content = "Relaxe, especialmente quando somos apenas nós dois.",
  ui_story_5057_50570601_54_dialog_content = "Por enquanto, eu quero sair e relaxar com você como amigo, PlayerName.",
  ui_story_5057_50570601_55_dialog_content = "Mas estou um pouco desanimado porque você sempre me coloca em um pedestal alto.",
  ui_story_5057_50570601_56_dialog_content = "Por favor, me trate apenas como um amigo por enquanto. Fique à vontade para brincar e fazer piadas.",
  ui_story_5057_50570601_57_dialog_content = "Não vou me importar com qualquer gafe que você possa cometer, e isso tornará nossas férias melhores e nos aproximará.",
  ui_story_5057_50570601_58_dialog_content = "Por favor, perdoe minha ignorância. Entendi o que você está dizendo agora.",
  ui_story_5057_50570601_59_dialog_content = "Vou começar a tratá-lo como um amigo a partir de agora, Vossa Majestade.",
  ui_story_5057_50570601_60_dialog_content = "Tudo bem.",
  ui_story_5057_50570601_61_dialog_content = "(Ela está sorrindo finalmente...)",
  ui_story_5057_50570601_62_dialog_content = "Acho que posso relaxar agora.",
  ui_story_5057_50570601_63_dialog_content = "Ah, mais uma coisa.",
  ui_story_5057_50570601_64_dialog_content = "O que é, Sua Majestade?",
  ui_story_5057_50570601_65_dialog_content = "De agora em diante, por favor, pare de me chamar de Vossa Majestade ou Queen.",
  ui_story_5057_50570601_66_dialog_content = "Eu não desejo que outros convidados saibam minha identidade.",
  ui_story_5057_50570601_67_dialog_content = "Bem, como eu contorno isso...?",
  ui_story_5057_50570601_68_dialog_content = "Belen.",
  ui_story_5057_50570601_69_dialog_content = "Me chame de Belen enquanto estou aqui.",
  ui_story_5057_50570601_70_dialog_content = "O quê?",
  ui_story_5057_50570601_71_dialog_content = "<color=#e8d9bb>EveEmbora Queen Bethlehem mantenha sua expressão calma e composta, posso perceber que seu ânimo melhorou bastante.</color>",
  ui_story_5057_50570602_1_dialog_content = "O céu azul é realmente demais para mim...",
  ui_story_5057_50570602_2_dialog_content = "Sinto que uma parte de mim é arrancada do meu corpo toda vez que sou empurrado e fico pulando para cima e para baixo.",
  ui_story_5057_50570602_3_dialog_content = "Mas Queen Bethlehem parece estar se divertindo muito.",
  ui_story_5057_50570602_4_dialog_content = "Eu estava pensando se poderia ser perigoso para ela.",
  ui_story_5057_50570602_5_dialog_content = "Acho que me preocupei à toa.",
  ui_story_5057_50570602_6_dialog_content = "Ufa...",
  ui_story_5057_50570602_7_dialog_content = "Bete... Belen, seu cabelo está uma bagunça.",
  ui_story_5057_50570602_8_option_content = "Ajuda Bethlehem a arrumar",
  ui_story_5057_50570602_9_dialog_content = "Por favor, permita-me dar uma mão.",
  ui_story_5057_50570602_10_dialog_content = "Claro, valeu.",
  ui_story_5057_50570602_11_option_content = "Aguarde Bethlehem arrumar-se",
  ui_story_5057_50570602_12_dialog_content = "Tudo bem, eu posso lidar com isso sozinho.",
  ui_story_5057_50570602_13_dialog_content = "Desculpe, quase te chamei pelo nome errado novamente.",
  ui_story_5057_50570602_14_dialog_content = "Não fique nervoso, eu sei que levará algum tempo para se acostumar. Apenas relaxe.",
  ui_story_5057_50570602_15_dialog_content = "Vai fazer! Você parece estar de muito melhor ânimo. Gostou do Céu Azul?",
  ui_story_5057_50570602_16_dialog_content = "(Só me lembra de Queen Bethlehem atirando com mais de uma dúzia de armas jogando aquele jogo de Roleta da Sorte.)",
  ui_story_5057_50570602_17_dialog_content = "(A chance de pegar uma arma descarregada nesse jogo é de uma em seis... Ela tem uma sorte incrível.)",
  ui_story_5057_50570602_18_dialog_content = "Este é mais divertido para mim... Eu só não tenho a chance de relaxar como pessoas normais, geralmente.",
  ui_story_5057_50570602_19_dialog_content = "Eu posso ver que, como rainha, você tem muitas coisas em mãos.",
  ui_story_5057_50570602_20_dialog_content = "Obrigado, mas não esqueça que sou Belen agora.",
  ui_story_5057_50570602_21_dialog_content = "Foi mal! Como pedido de desculpas, aproveite um copo de suco de cacto estrela por minha conta! É muito gostoso.",
  ui_story_5057_50570602_22_dialog_content = "Então podemos ir relaxar na roda-gigante e apreciar a vista do resort.",
  ui_story_5057_50570602_23_dialog_content = "Já volto.",
  ui_story_5057_50570602_24_dialog_content = "Não acredito como o vendedor estava lotado. Foi um longo tempo de espera.",
  ui_story_5057_50570602_25_dialog_content = "Preciso voltar. Queen Bethlehem deve estar se perguntando onde estou.",
  ui_story_5057_50570602_26_dialog_content = "Então, o que você diz, senhorita?",
  ui_story_5057_50570602_27_dialog_content = "Fique à vontade para dar sua opinião.",
  ui_story_5057_50570602_28_dialog_content = "...",
  ui_story_5057_50570602_29_dialog_content = "Quem são essas pessoas?",
  ui_story_5057_50570602_30_dialog_content = "Oi, amigo. Você e essa mocinha são amigos?",
  ui_story_5057_50570602_31_dialog_content = "Quem é você?",
  ui_story_5057_50570602_32_dialog_content = "Desculpe pela grosseria. Na verdade, sou um olheiro da Umbraton Beatitude Entertainment.",
  ui_story_5057_50570602_33_dialog_content = "E devo dizer que esta mocinha aqui tem uma aparência absolutamente deslumbrante. Ela é como uma estrela nascida.",
  ui_story_5057_50570602_34_dialog_content = "Nossa empresa é altamente influente e, se você estiver interessado em se juntar a nós, posso apresentar-lhe algumas condições excepcionalmente atraentes!",
  ui_story_5057_50570602_35_dialog_content = "Estamos aqui de férias e não temos planos de nos tornar um ídolo ou algo assim.",
  ui_story_5057_50570602_36_dialog_content = "Seria uma pena desperdiçar um talento e potencial tão incríveis!",
  ui_story_5057_50570602_37_dialog_content = "Ei, colega. Você é o agente desta jovem?",
  ui_story_5057_50570602_38_dialog_content = "Podemos ter uma discussão entre três pessoas e posso prometer-lhe uma comissão substancial.",
  ui_story_5057_50570602_39_dialog_content = "Me perdoe, mas não queremos ser incomodados.",
  ui_story_5057_50570602_40_dialog_content = "Que pena. Bem, vou ter que procurar outra pessoa.",
  ui_story_5057_50570602_41_dialog_content = "Senhorita, posso deixar meu contato com você? Tenho algumas oportunidades fantásticas para você!",
  ui_story_5057_50570602_42_dialog_content = "Por favor, saia agora, ou vou chamar a segurança.",
  ui_story_5057_50570602_43_dialog_content = "Maninho, o que você acabou de dizer...?",
  ui_story_5057_50570602_44_dialog_content = "Por favor, fique atrás de mim, Srta. Belen.",
  ui_story_5057_50570602_45_dialog_content = "Já chega, Duque. Somos empresários agora.",
  ui_story_5057_50570602_46_dialog_content = "Hahaha, meu amigo aqui realmente tem um temperamento forte.",
  ui_story_5057_50570602_47_dialog_content = "Deixaremos vocês dois a sós. Preciso dizer, seu amigo é bem durão, senhorita.",
  ui_story_5057_50570602_48_dialog_content = "Tsc.",
  ui_story_5057_50570602_49_dialog_content = "Inacreditável, o cara simplesmente não desistia.",
  ui_story_5057_50570602_50_dialog_content = "Está tudo bem, Sua Majestade? Desculpe pelo atraso.",
  ui_story_5057_50570602_51_dialog_content = "Estou bem, PlayerName. Eu não me preocupo com esse tipo de pessoa ou assédio.",
  ui_story_5057_50570602_52_dialog_content = "Eu estive observando você.",
  ui_story_5057_50570602_53_dialog_content = "Me observando?",
  ui_story_5057_50570602_54_dialog_content = "<color=#e8d9bb>Bethlehem coloca a mão no meu ombro.</color>",
  ui_story_5057_50570602_55_dialog_content = "Sim. A coragem que você demonstrou foi muito louvável.",
  ui_story_5057_50570602_56_dialog_content = "Analisando como eles agem, provavelmente trabalhavam como executores em Umbraton.",
  ui_story_5057_50570602_57_dialog_content = "Se houver um confronto, eu não acho que você possa vencer qualquer um deles, sem falar que você está em desvantagem numérica.",
  ui_story_5057_50570602_58_dialog_content = "Ah, isso foi perigoso, não foi? Isso não passou pela minha cabeça...",
  ui_story_5057_50570602_59_dialog_content = "E é exatamente por isso que você é admirado.",
  ui_story_5057_50570602_60_dialog_content = "Você se tornou mais corajoso e confiável.",
  ui_story_5057_50570602_61_dialog_content = "Você realmente é o escolhido.",
  ui_story_5057_50570602_62_dialog_content = "Está me fazendo corar, Vossa Majestade.",
  ui_story_5057_50570602_63_dialog_content = "Tudo bem, vamos para a roda-gigante. E não se esqueça, agora sou Belen.",
  ui_story_5057_50570602_64_dialog_content = "<color=#e8d9bb>Então eu ando na roda-gigante com Bethlehem... Quer dizer, Belen. Não consigo deixar de notar que Sua Majestade, que geralmente tem um olhar gélido, parece muito mais suave nos olhos hoje.</color>",
  ui_story_5057_50570701_1_dialog_content = "Eu-Estou nervoso.",
  ui_story_5057_50570701_2_dialog_content = "Claro, sou amigo de Sua Majestade Bethlehem...",
  ui_story_5057_50570701_3_dialog_content = "Mas ainda fico estressado ao encontrar com ela sozinho, por alguma razão...",
  ui_story_5057_50570701_4_dialog_content = "Sem mencionar que estou representando o resort em nome de Lorelei...",
  ui_story_5057_50570701_5_dialog_content = "Estou apresentável, certo...? Ah, eu estava usando isso o tempo todo.",
  ui_story_5057_50570701_6_dialog_content = "Então, provavelmente não vou envergonhar os Celestitas... Espero que não...",
  ui_story_5057_50570701_7_dialog_content = "E, esperamos que também não seja um constrangimento para o resort.",
  ui_story_5057_50570701_8_dialog_content = "PlayerName...",
  ui_story_5057_50570701_9_dialog_content = "Lorelei não descontaria meu salário, descontaria?",
  ui_story_5057_50570701_10_dialog_content = "PlayerName?",
