  ui_story_5057_50570701_16_dialog_content = "Lorelei tem se culpado por não ter te entretido antes, pois estava ocupada com Eclipsitas.",
  ui_story_5057_50570701_17_dialog_content = "E espero que você aproveite bem estas raras férias no resort.",
