  ui_story_5057_50570701_22_dialog_content = "Mas você parece calmo e controlado, Vossa Majestade.",
  ui_story_5057_50570701_23_dialog_content = "De fato, já que estou acostumado a cavalgar um dragão voador.",
  ui_story_5057_50570701_24_dialog_content = "Você realmente vivenciou tudo, Vossa Majestade.",
  ui_story_5057_50570701_25_dialog_content = "Chá e lanche para você.",
  ui_story_5057_50570701_26_dialog_content = "Obrigada, PlayerName.",
  ui_story_5057_50570701_27_dialog_content = "Onde está sua porção?",
