  ui_story_5057_50570701_29_dialog_content = "Ouvi dizer que ele usou muitos ingredientes preciosos e caros.",
  ui_story_5057_50570701_30_dialog_content = "É mesmo?",
  ui_story_5057_50570701_31_dialog_content = "(Hmm, acho que Queen Bethlehem não está com um ânimo muito bom.)",
  ui_story_5057_50570701_32_dialog_content = "PlayerName.",
  ui_story_5057_50570701_33_dialog_content = "Muito bem, Vossa Majestade!",
  ui_story_5057_50570701_34_dialog_content = "Eu tenho uma pergunta.",
