  ui_story_5057_50570701_47_dialog_content = "Sua atitude está me fazendo sentir como se estivesse em uma função oficial.",
  ui_story_5057_50570701_48_dialog_content = "Desculpe...",
  ui_story_5057_50570701_49_dialog_content = "Por favor, não abaixe a cabeça, Celestita. Você ainda se lembra que é o escolhido?",
  ui_story_5057_50570701_50_dialog_content = "Claro que eu faço!",
  ui_story_5057_50570701_51_dialog_content = "Se você realmente quer me ajudar a aliviar o estresse...",
  ui_story_5057_50570701_52_dialog_content = "Então me ajude a esquecer meu status de rainha e pular esses protocolos formais.",
  ui_story_5057_50570701_53_dialog_content = "Relaxe, especialmente quando somos apenas nós dois.",
  ui_story_5057_50570701_54_dialog_content = "Por enquanto, quero sair e relaxar com você como amigo, PlayerName.",
  ui_story_5057_50570701_55_dialog_content = "Mas estou um pouco desanimado porque você sempre me coloca em um pedestal alto.",
  ui_story_5057_50570701_56_dialog_content = "Por favor, me trate apenas como um amigo por enquanto. Fique à vontade para brincar e fazer piadas.",
  ui_story_5057_50570701_57_dialog_content = "Não vou me importar com qualquer gafe que você possa cometer, e isso tornará nossas férias melhores e nos aproximará.",
  ui_story_5057_50570701_58_dialog_content = "Por favor, perdoe minha ignorância. Entendi o que você está dizendo agora.",
  ui_story_5057_50570701_59_dialog_content = "Vou começar a tratá-lo como um amigo a partir de agora, Vossa Majestade.",
  ui_story_5057_50570701_60_dialog_content = "Tudo bem.",
  ui_story_5057_50570701_61_dialog_content = "(Ela está sorrindo finalmente...)",
  ui_story_5057_50570701_62_dialog_content = "Acho que posso relaxar agora.",
  ui_story_5057_50570701_63_dialog_content = "Ah, mais uma coisa.",
  ui_story_5057_50570701_64_dialog_content = "O que é, Sua Majestade?",
  ui_story_5057_50570701_65_dialog_content = "De agora em diante, por favor, pare de me chamar de Vossa Majestade ou Queen.",
  ui_story_5057_50570701_66_dialog_content = "Eu não desejo que outros convidados saibam minha identidade.",
  ui_story_5057_50570701_67_dialog_content = "Bem, como eu contorno isso...?",
  ui_story_5057_50570701_68_dialog_content = "Belen.",
  ui_story_5057_50570701_69_dialog_content = "Me chame de Belen enquanto estou aqui.",
  ui_story_5057_50570701_70_dialog_content = "O quê?",
  ui_story_5057_50570701_71_dialog_content = "<color=#e8d9bb>EveEmbora Queen Bethlehem mantenha sua expressão calma e composta, posso perceber que seu ânimo melhorou bastante.</color>",
  ui_story_5057_50570702_1_dialog_content = "O céu azul é realmente demais para mim...",
  ui_story_5057_50570702_2_dialog_content = "Sinto que uma parte de mim é arrancada do meu corpo toda vez que sou empurrado e fico pulando para cima e para baixo.",
  ui_story_5057_50570702_3_dialog_content = "Mas Queen Bethlehem parece estar se divertindo muito.",
  ui_story_5057_50570702_4_dialog_content = "Eu estava pensando se poderia ser perigoso para ela.",
  ui_story_5057_50570702_5_dialog_content = "Acho que me preocupei à toa.",
  ui_story_5057_50570702_6_dialog_content = "Ufa...",
  ui_story_5057_50570702_7_dialog_content = "Bete... Belen, seu cabelo está uma bagunça.",
  ui_story_5057_50570702_8_option_content = "Ajuda Bethlehem a arrumar",
  ui_story_5057_50570702_9_dialog_content = "Por favor, permita-me dar-lhe uma mão.",
  ui_story_5057_50570702_10_dialog_content = "Claro, valeu.",
  ui_story_5057_50570702_11_option_content = "Aguarde Bethlehem arrumar-se",
  ui_story_5057_50570702_12_dialog_content = "Tudo bem, eu posso lidar com isso sozinho.",
  ui_story_5057_50570702_13_dialog_content = "Desculpe, quase te chamei pelo nome errado novamente.",
  ui_story_5057_50570702_14_dialog_content = "Não fique nervoso, eu sei que levará algum tempo para se acostumar. Apenas relaxe.",
  ui_story_5057_50570702_15_dialog_content = "Vai fazer! Você parece estar de muito melhor ânimo. Gostou do Céu Azul?",
  ui_story_5057_50570702_16_dialog_content = "(Só me lembra de Queen Bethlehem atirando com mais de uma dúzia de armas jogando aquele jogo de Roleta da Sorte.)",
  ui_story_5057_50570702_17_dialog_content = "(A chance de pegar uma arma descarregada nesse jogo é de uma em seis... Ela tem uma sorte incrível.)",
  ui_story_5057_50570702_18_dialog_content = "Este é mais divertido para mim... Eu só não tenho a chance de relaxar como pessoas normais, geralmente.",
  ui_story_5057_50570702_19_dialog_content = "Eu posso ver que, como rainha, você tem muitas coisas em mãos.",
  ui_story_5057_50570702_20_dialog_content = "Obrigado, mas não esqueça que sou Belen agora.",
  ui_story_5057_50570702_21_dialog_content = "Foi mal! Como pedido de desculpas, aproveite um copo de suco de cacto estrela por minha conta! É muito gostoso.",
  ui_story_5057_50570702_22_dialog_content = "Então podemos ir relaxar na roda-gigante e negligenciar o resort.",
  ui_story_5057_50570702_23_dialog_content = "Já volto.",
  ui_story_5057_50570702_24_dialog_content = "Não acredito como o vendedor estava lotado. Foi um longo tempo de espera.",
  ui_story_5057_50570702_25_dialog_content = "Eu preciso voltar. Queen Bethlehem deve estar se perguntando onde estou.",
  ui_story_5057_50570702_26_dialog_content = "Então, o que você diz, senhorita?",
  ui_story_5057_50570702_27_dialog_content = "Fique à vontade para dar sua opinião.",
  ui_story_5057_50570702_28_dialog_content = "...",
  ui_story_5057_50570702_29_dialog_content = "Quem são essas pessoas?",
  ui_story_5057_50570702_30_dialog_content = "Oi, amigo. Você e essa mocinha são amigos?",
  ui_story_5057_50570702_31_dialog_content = "Quem é você?",
  ui_story_5057_50570702_32_dialog_content = "Desculpe pela grosseria. Na verdade, sou um olheiro da Umbraton Beatitude Entertainment.",
  ui_story_5057_50570702_33_dialog_content = "E devo dizer que esta mocinha aqui tem uma aparência absolutamente deslumbrante. Ela é como uma estrela nascida.",
  ui_story_5057_50570702_34_dialog_content = "Nossa empresa é altamente influente e, se você estiver interessado em se juntar a nós, posso apresentar-lhe algumas condições excepcionalmente atraentes!",
  ui_story_5057_50570702_35_dialog_content = "Estamos aqui de férias e não temos planos de nos tornar um ídolo ou algo assim.",
  ui_story_5057_50570702_36_dialog_content = "Seria uma pena desperdiçar um talento e potencial tão incríveis!",
  ui_story_5057_50570702_37_dialog_content = "Ei, amigo. Você e essa mocinha são amigos?",
  ui_story_5057_50570702_38_dialog_content = "Podemos ter uma discussão entre três pessoas e posso prometer-lhe uma comissão substancial.",
  ui_story_5057_50570702_39_dialog_content = "Me perdoe, mas não queremos ser incomodados.",
  ui_story_5057_50570702_40_dialog_content = "Que pena. Bem, vou ter que procurar outra pessoa.",
  ui_story_5057_50570702_41_dialog_content = "Senhorita, posso deixar meu contato com você? Tenho algumas oportunidades fantásticas para você!",
  ui_story_5057_50570702_42_dialog_content = "Por favor, saia agora ou chamarei a segurança.",
  ui_story_5057_50570702_43_dialog_content = "Mané, o que você acabou de dizer...?",
  ui_story_5057_50570702_44_dialog_content = "Por favor, fique atrás de mim, Srta. Belen.",
  ui_story_5057_50570702_45_dialog_content = "Já chega, Duque. Somos empresários agora.",
  ui_story_5057_50570702_46_dialog_content = "Hahaha, meu amigo aqui realmente tem um temperamento forte.",
  ui_story_5057_50570702_47_dialog_content = "Deixaremos vocês dois a sós. Preciso dizer, seu amigo é bem durão, senhorita.",
  ui_story_5057_50570702_48_dialog_content = "Tsc.",
  ui_story_5057_50570702_49_dialog_content = "Inacreditável, o cara simplesmente não desistia.",
  ui_story_5057_50570702_50_dialog_content = "Está tudo bem, Sua Majestade? Desculpe pelo atraso.",
  ui_story_5057_50570702_51_dialog_content = "Estou bem, PlayerName. Eu não me preocupo com esse tipo de pessoa ou assédio.",
  ui_story_5057_50570702_52_dialog_content = "Estou te observando.",
  ui_story_5057_50570702_53_dialog_content = "Me observando?",
  ui_story_5057_50570702_54_dialog_content = "(Bethlehem coloca a mão no meu ombro.)",
  ui_story_5057_50570702_55_dialog_content = "Sim. A coragem que você demonstrou foi muito louvável.",
  ui_story_5057_50570702_56_dialog_content = "Julgando pelo modo como agem, provavelmente trabalharam como executores em Umbraton.",
  ui_story_5057_50570702_57_dialog_content = "Se houver um confronto, eu não acho que você possa vencer qualquer um deles, sem falar que você está em desvantagem numérica.",
  ui_story_5057_50570702_58_dialog_content = "Ah, isso foi perigoso, não foi? Isso não passou pela minha cabeça...",
  ui_story_5057_50570702_59_dialog_content = "E é exatamente por isso que você é admirado.",
  ui_story_5057_50570702_60_dialog_content = "Você se tornou mais corajoso e confiável.",
  ui_story_5057_50570702_61_dialog_content = "Você realmente é o Escolhido.",
  ui_story_5057_50570702_62_dialog_content = "Está me fazendo corar, Vossa Majestade.",
  ui_story_5057_50570702_63_dialog_content = "Tudo bem, vamos para a roda-gigante. E não se esqueça, agora sou Belen.",
  ui_story_5057_50570702_64_dialog_content = "<color=#e8d9bb>Então eu ando na roda-gigante com Bethlehem... Quer dizer, Belen. Não posso deixar de notar que Sua Majestade, que geralmente tem um olhar gélido, parece muito mais suave nos olhos hoje.</color>",
  ui_story_5057_50570801_1_dialog_content = "PlayerName！",
  ui_story_5057_50570801_2_dialog_content = "Hã?",
  ui_story_5057_50570801_3_dialog_content = "PlayerName!!",
  ui_story_5057_50570801_4_dialog_content = "Acho que ouço uma voz perturbadora chamando meu nome...",
  ui_story_5057_50570801_5_dialog_content = "Eu deveria sair.",
  ui_story_5057_50570801_6_dialog_content = "PlayerName—",
  ui_story_5057_50570801_7_dialog_content = "E-Espera, eu não consigo acompanhar você.",
  ui_story_5057_50570801_8_dialog_content = "Vou desmaiar se você continuar assim—",
  ui_story_5057_50570801_9_dialog_content = "Vic?",
  ui_story_5057_50570801_10_dialog_content = "Desculpe, senti que algo ruim estava chegando e simplesmente acelerei o passo.",
  ui_story_5057_50570801_11_dialog_content = "É isso que você pensa de mim? Isso me deixa triste.",
  ui_story_5057_50570801_12_dialog_content = "Então, por que você não compensa me convidando para almoçar?",
  ui_story_5057_50570801_13_dialog_content = "O extrozoólogo mais famoso do mundo certamente agraciará você com sua presença.",
  ui_story_5057_50570801_14_dialog_content = "Pare de tentar aproveitar!",
  ui_story_5057_50570801_15_dialog_content = "E sobre o que você estava tagarelando? Eu não sou um dos seus aprendizes.",
  ui_story_5057_50570801_16_dialog_content = "Qual a diferença isso faz? Tenho certeza de que você se deu muito bem com Fia e Shira.",
  ui_story_5057_50570801_17_dialog_content = "Não... Esqueça o Fia, como você poderia dizer com o Shira?",
  ui_story_5057_50570801_18_dialog_content = "Chame isso de intuição de mestre e não vou entrar em detalhes específicos.",
  ui_story_5057_50570801_19_dialog_content = "Então, já pensou em levar o relacionamento um passo adiante?",
  ui_story_5057_50570801_20_dialog_content = "Então todos seremos uma família e você também terá que me chamar de \"Mestre\".",
  ui_story_5057_50570801_21_dialog_content = "Quem você acha que é melhor para você, Fia ou Shira?",
  ui_story_5057_50570801_22_option_content = "As Bestas Maravilhosas!",
  ui_story_5057_50570801_23_dialog_content = "Ei, eu não esperava que você tivesse um interesse comum.",
  ui_story_5057_50570801_24_dialog_content = "Algumas criaturas são tão incríveis quanto eu, não apenas na personalidade, mas também na mesma cor linda...",
  ui_story_5057_50570801_25_dialog_content = "Você está se referindo àquele boros que encontramos antes?",
  ui_story_5057_50570801_26_dialog_content = "Isso mesmo. Por favor, veja meu novo livro, \"O Mistério Entre Eu e Ouroboros\" para detalhes.",
  ui_story_5057_50570801_27_dialog_content = "Ainda estou trabalhando nisso, então você pode aguardar ansiosamente por enquanto.",
  ui_story_5057_50570801_28_dialog_content = "Falando nisso, você também ficou encantado com a linda figura dele?",
  ui_story_5057_50570801_29_dialog_content = "Vamos, embarquemos nas trilhas do Ouroboros e nos tornemos supremos extrozoólogos!",
  ui_story_5057_50570801_30_dialog_content = "Não, obrigado, eu estava apenas brincando!",
  ui_story_5057_50570801_31_dialog_content = "E o que é essa coisa suprema de repente?",
  ui_story_5057_50570801_32_dialog_content = "Por favor, pare com as suposições malucas!",
  ui_story_5057_50570801_33_dialog_content = "Vou com o Mestre Vic!",
  ui_story_5057_50570801_34_option_content = "Escolha o Mestre Vic!",
  ui_story_5057_50570801_35_dialog_content = "...",
  ui_story_5057_50570801_36_dialog_content = "Hum...",
  ui_story_5057_50570801_37_dialog_content = "...",
  ui_story_5057_50570801_38_dialog_content = "Espere, que tipo de expressão é essa?",
  ui_story_5057_50570801_39_dialog_content = "Tudo bem, estou apenas emocionado até às lágrimas.",
  ui_story_5057_50570801_40_dialog_content = "Era isso que eu queria saber. Por que você está chorando?",
  ui_story_5057_50570801_41_dialog_content = "Eu não achei que você se abriria comigo assim, PlayerName.",
  ui_story_5057_50570801_42_dialog_content = "A emoção e paixão que você demonstrou para mim...",
  ui_story_5057_50570801_43_dialog_content = "Isso me emocionou muito.",
  ui_story_5057_50570801_44_dialog_content = "Não consegue perceber que estou zombando de você? Não, você deve estar fingindo.",
  ui_story_5057_50570801_45_dialog_content = "Infelizmente, eu fiz um juramento.",
  ui_story_5057_50570801_46_dialog_content = "Passarei minha vida inteira com bestas maravilhosas. Não é mesmo, pequena bola de pêlo.",
  ui_story_5057_50570801_47_dialog_content = "Piu!",
  ui_story_5057_50570801_48_dialog_content = "O quê? Você disse que os Celestitas são bestas maravilhosas em certo sentido?",
  ui_story_5057_50570801_49_dialog_content = "Então ele está dentro do meu leque de opções?",
  ui_story_5057_50570801_50_dialog_content = "Você também ficará feliz, se eu estiver com PlayerName?",
  ui_story_5057_50570801_51_dialog_content = "Foi apenas um piado... Como você conseguiu tirar tanto disso?",
  ui_story_5057_50570801_52_dialog_content = "Agora eu acho que você está puxando minha perna.",
  ui_story_5057_50570801_53_dialog_content = "Heehee, brincadeira.",
  ui_story_5057_50570801_54_dialog_content = "E isso com certeza não pode passar por cima da cabeça do esperto PlayerName, não é?",
  ui_story_5057_50570801_55_dialog_content = "Ha, tanto o mestre quanto os aprendizes são difíceis de lidar.",
  ui_story_5057_50570801_56_dialog_content = "Então, o que você quer comigo, já que provavelmente não está aqui apenas para bater papo?",
  ui_story_5057_50570801_57_dialog_content = "Eu sabia que você era um atirador direto!",
  ui_story_5057_50570801_58_dialog_content = "É uma intuição que tenho por ter lidado com você e seus aprendizes muitas vezes.",
  ui_story_5057_50570801_59_dialog_content = "Então não vamos esperar! Rápido, para a ecozona.",
  ui_story_5057_50570801_60_dialog_content = "Ecozona?",
  ui_story_5057_50570801_61_dialog_content = "Pare de me arrastar! Por que você e Fia fazem isso o tempo todo?",
  ui_story_5057_50570801_62_dialog_content = "<color=#e8d9bb>No caminho, Vic me ofereceu um delicioso sorvete.</color>",
  ui_story_5057_50570801_63_dialog_content = "<color=#e8d9bb>Entretanto, só depois de terminarmos foi que ele me disse que tinha esquecido a carteira...</color>",
  ui_story_5057_50570802_1_dialog_content = "Ah, o sorvete não é ruim.",
  ui_story_5057_50570802_2_dialog_content = "Obrigado pelo mimo, PlayerName!",
  ui_story_5057_50570802_3_dialog_content = "Não acredito que você tenha a audácia de dizer isso.",
  ui_story_5057_50570802_4_dialog_content = "Felizmente, Vice colocou algum troco no meu bolso.",
  ui_story_5057_50570802_5_dialog_content = "Caso contrário, estaríamos sem sorte.",
  ui_story_5057_50570802_6_dialog_content = "Você tem sorte, PlayerName, por ter Vice cuidando de você e te dando dinheiro.",
  ui_story_5057_50570802_7_dialog_content = "Tudo que meus aprendizes sabem fazer é me extorquir.",
  ui_story_5057_50570802_8_dialog_content = "Mas você também não manda neles o dia inteiro?",
  ui_story_5057_50570802_9_dialog_content = "O que vai, volta.",
  ui_story_5057_50570802_10_dialog_content = "Isso não é mandar neles. É chamado de treinamento.",
  ui_story_5057_50570802_11_dialog_content = "Sem o treinamento sem folga durante todo o ano que estabeleci para eles, eles não seriam tão notáveis tão cedo.",
  ui_story_5057_50570802_12_dialog_content = "Que mentiroso...",
  ui_story_5057_50570802_13_dialog_content = "Hahaha... Esqueça isso, estamos aqui.",
  ui_story_5057_50570802_14_dialog_content = "Esta é a ecozona?",
  ui_story_5057_50570802_15_dialog_content = "Hiya!",
  ui_story_5057_50570802_16_dialog_content = "Hiya!",
  ui_story_5057_50570802_17_dialog_content = "Gloo...",
  ui_story_5057_50570802_18_dialog_content = "Eles não são Bica e Glooey?",
  ui_story_5057_50570802_19_dialog_content = "Eu não esperava vê-los aqui de jeito nenhum.",
  ui_story_5057_50570802_20_dialog_content = "Sinceramente, eu também não achava que eles conseguiriam sobreviver aqui.",
  ui_story_5057_50570802_21_dialog_content = "Bica geralmente prefere viver em montanhas isoladas.",
  ui_story_5057_50570802_22_dialog_content = "E Glooey adorava habitats com fontes abundantes de água.",
  ui_story_5057_50570802_23_dialog_content = "Even quando Glooey avistamentos foram relatados em áreas secas, eles já haviam desaparecido quando chegamos lá.",
  ui_story_5057_50570802_24_dialog_content = "Fia não estava lá da última vez, e eu me esforcei por três dias sem parar para alcançá-lo.",
  ui_story_5057_50570802_25_dialog_content = "Passei o dia inteiro vasculhando o lugar, depois acampei por mais duas semanas só porque.",
  ui_story_5057_50570802_26_dialog_content = "Eu estava com tanta pressa que esqueci de levar equipamento de acampamento, então dormi com a pequena bola de pêlo nos meus braços todas as noites.",
  ui_story_5057_50570802_27_dialog_content = "Eu não voltei até ter certeza absoluta de que nenhum Glooey apareceria.",
  ui_story_5057_50570802_28_dialog_content = "Que trabalho difícil você tem...",
  ui_story_5057_50570802_29_dialog_content = "Nah, não é nada.",
  ui_story_5057_50570802_30_dialog_content = "Tudo em um dia de trabalho de um extrozoólogo.",
  ui_story_5057_50570802_31_dialog_content = "Eu continuava lembrando Fia de se equipar antes de sair, mas sempre esquecia quando se tratava de mim mesmo.",
  ui_story_5057_50570802_32_option_content = "Mayeu posso ajudar com isso.",
  ui_story_5057_50570802_33_dialog_content = "Me avise antes de fazer uma viagem longa. Se o tempo permitir, Soroz pode te levar até lá.",
  ui_story_5057_50570802_34_dialog_content = "E você pode guardar alguns equipamentos em Soroz para não esquecer.",
  ui_story_5057_50570802_35_dialog_content = "Hmmm... que boa ideia.",
  ui_story_5057_50570802_36_dialog_content = "Isso é muito atencioso da sua parte, PlayerName.",
  ui_story_5057_50570802_37_option_content = "Envie Fia na próxima vez",
  ui_story_5057_50570802_38_dialog_content = "Você está certo, haha.",
  ui_story_5057_50570802_39_dialog_content = "Meu corpo é velho demais para aguentar a tortura!",
  ui_story_5057_50570802_40_dialog_content = "É melhor eu ficar em casa, cuidar do meu jardim e olhar pelos pequenos bichinhos.",
  ui_story_5057_50570802_41_dialog_content = "Mas era urgente naquela época, pois o Glooey aparecendo em terras secas poderia ser uma subespécie rara.",
  ui_story_5057_50570802_42_dialog_content = "Se eu pudesse documentá-los, eu poderia fazer as pessoas entenderem e amá-los mais...",
  ui_story_5057_50570802_43_dialog_content = "Gloo...",
  ui_story_5057_50570802_44_dialog_content = "Claro, o Buck também é muito especial.",
  ui_story_5057_50570802_45_dialog_content = "Every Glooey é único para mim.",
  ui_story_5057_50570802_46_dialog_content = "Gloo...",
  ui_story_5057_50570802_47_dialog_content = "Gloo...",
  ui_story_5057_50570802_48_dialog_content = "Mestre Vic, as Glooey e Bica que habitam o Deserto Rediesel também são espécies especiais?",
  ui_story_5057_50570802_49_dialog_content = "Não, eles não estão.",
  ui_story_5057_50570802_50_dialog_content = "Eles foram abandonados no deserto de Rediesel.",
  ui_story_5057_50570802_51_dialog_content = "O quê?!",
  ui_story_5057_50570802_52_dialog_content = "Sim, estou adivinhando que os caras que traficavam bestas maravilhosas são responsáveis.",
  ui_story_5057_50570802_53_dialog_content = "Eu não sei o motivo ainda. Maytalvez eles não conseguiram o preço que queriam ou algo assim.",
  ui_story_5057_50570802_54_dialog_content = "Mas essas coisas terríveis apenas deixaram as feras onde tinham dificuldade em sobreviver...",
  ui_story_5057_50570802_55_dialog_content = "Gloo...",
  ui_story_5057_50570802_56_dialog_content = "Tenho um favor para te pedir, PlayerName.",
  ui_story_5057_50570802_57_dialog_content = "Entendo como algumas das bestas maravilhosas falam, mas não consigo realmente entender o que elas pensam.",
  ui_story_5057_50570802_58_dialog_content = "Você pode usar sua habilidade psíquica neles e convencê-los a me dizer quem fez isso?",
  ui_story_5057_50570802_59_dialog_content = "Eu preciso obter justiça para eles.",
  ui_story_5057_50570802_60_dialog_content = "Entendido.",
  ui_story_5057_50570802_61_dialog_content = "Gloo... Sr. Vic...",
  ui_story_5057_50570802_62_dialog_content = "Eu posso ouvir agora... Me diga, quem fez isso com você e a qual gangue eles pertencem?",
  ui_story_5057_50570802_63_dialog_content = "Aquela pessoa era... Gloo...",
  ui_story_5057_50570802_64_dialog_content = "Foi Bica...",
  ui_story_5057_50570802_65_dialog_content = "Então, estávamos pegando carona na aeronave...",
  ui_story_5057_50570802_66_dialog_content = "Mas o Bica bagunçou tudo... E agora acabamos caindo aqui.",
  ui_story_5057_50570802_67_dialog_content = "Hiya!",
  ui_story_5057_50570802_68_dialog_content = "Ok...",
  ui_story_5057_50570802_69_dialog_content = "Parece que você obteve sua resposta, Vic.",
  ui_story_5057_50570802_70_dialog_content = "Sim, tudo está bem e perfeito agora.",
  ui_story_5057_50570802_71_dialog_content = "Quem sabe, talvez eu até tenha me livrado de alguns daquele bando de criminosos inadvertidamente antes.",
  ui_story_5057_50570802_72_dialog_content = "Quanto mais, melhor. Afinal, são criminosos.",
  ui_story_5057_50570802_73_dialog_content = "Agora eu sei por que Fia adorava ir em aventuras com você, PlayerName.",
  ui_story_5057_50570802_74_dialog_content = "EveJá pensou em me seguir?",
  ui_story_5057_50570802_75_dialog_content = "Posso encontrar um Kyllo para você...",
  ui_story_5057_50570802_76_dialog_content = "Pare de me importunar!",
  ui_story_5057_50570802_77_dialog_content = "<color=#e8d9bb>E então, Vic continua me incomodando até que eu não aguente mais e assine alguns tratados desiguais.</color>",
  ui_story_5057_50570901_1_dialog_content = "Você está quase atrasado, PlayerName.",
  ui_story_5057_50570901_2_dialog_content = "Arf, arf... Desculpe... mas você acabou de me enviar a mensagem há alguns minutos atrás.",
  ui_story_5057_50570901_3_dialog_content = "Eu corri a toda velocidade até aqui...",
  ui_story_5057_50570901_4_dialog_content = "Bem, isso é verdade.",
  ui_story_5057_50570901_5_dialog_content = "Foi minha culpa te chamar tão de repente. Não deveria te culpar e peço desculpas.",
  ui_story_5057_50570901_6_dialog_content = "Mas você conseguiu correr até aqui... Parece que você se tornou muito mais forte do que antes.",
  ui_story_5057_50570901_7_dialog_content = "EveDesde que saí do subterrâneo, as coisas nunca param de acontecer, às vezes até perigosas.",
  ui_story_5057_50570901_8_dialog_content = "Ser perseguido por diferentes Eclipsitas o ano todo deixaria qualquer um em forma.",
  ui_story_5057_50570901_9_dialog_content = "Também ouvi dizer que você é um par para os Eclipsitas comuns agora.",
  ui_story_5057_50570901_10_dialog_content = "TakiLevando em conta suas habilidades psíquicas, você pode até superar os Aurorianos como guerreiro um dia.",
  ui_story_5057_50570901_11_dialog_content = "De jeito nenhum, ainda tenho um longo caminho a percorrer. Gostaria de ser forte o suficiente para proteger todos, mas ainda não estou lá.",
  ui_story_5057_50570901_12_dialog_content = "Astuto e humilde agora... Estou impressionado.",
  ui_story_5057_50570901_13_dialog_content = "Chega de conversa fiada, agora vamos ao motivo específico pelo qual quero te ver.",
  ui_story_5057_50570901_14_dialog_content = "Colocando-me para trabalhar agora? Eu estava tentando ganhar mais tempo conversando...",
  ui_story_5057_50570901_15_dialog_content = "Não reclame.",
  ui_story_5057_50570901_16_dialog_content = "Consegui um emprego recentemente com alguém que tem dicas sobre os contrabandistas em Umbraton e está disfarçado entre os convidados no Denuo Valley Resort.",
  ui_story_5057_50570901_17_dialog_content = "Ele é um informante astuto e bem relacionado. Ele escapou de todos que foram enviados para segui-lo ou capturá-lo.",
  ui_story_5057_50570901_18_dialog_content = "Mas é diferente para mim. Como raramente faço esse tipo de trabalho, ele não vai me reconhecer.",
  ui_story_5057_50570901_19_dialog_content = "Você pegou isso porque o dinheiro está ficando apertado?",
  ui_story_5057_50570901_20_dialog_content = "Sem comentários sobre minha situação financeira, a menos que você queira que eu te venda para o mercado negro.",
  ui_story_5057_50570901_21_dialog_content = "S-Desculpe! Por favor continue.",
  ui_story_5057_50570901_22_dialog_content = "De acordo com meu empregador, o mascate tem um talento especial para sentir a aproximação de grupos hostis.",
  ui_story_5057_50570901_23_dialog_content = "Então, devemos nos posicionar e esperar que ele apareça aqui.",
  ui_story_5057_50570901_24_dialog_content = "Preciso da sua ajuda para cobrir todas as bases.",
  ui_story_5057_50570901_25_dialog_content = "Finja ser meu par, entendeu?",
  ui_story_5057_50570901_26_dialog_content = "Entendi, ele podia sentir partes hostis...",
  ui_story_5057_50570901_27_dialog_content = "... então eu serei seu par... Par?!",
  ui_story_5057_50570901_28_dialog_content = "Oh, qual é o problema, querido?",
  ui_story_5057_50570901_29_dialog_content = "QUERIDO!",
  ui_story_5057_50570901_30_option_content = "Sim! O que foi?",
  ui_story_5057_50570901_31_dialog_content = "Nada. Apenas lembre-se do seu papel e pare de ficar aéreo.",
  ui_story_5057_50570901_32_option_content = "...",
  ui_story_5057_50570901_33_dialog_content = "PlayerName！",
  ui_story_5057_50570901_34_dialog_content = "Sim!",
  ui_story_5057_50570901_35_dialog_content = "Desculpe, não estou acostumado com isso...",
  ui_story_5057_50570901_36_dialog_content = "Não peça desculpas. É apenas um trabalho.",
  ui_story_5057_50570901_37_dialog_content = "Mas ainda assim, mantenha a cabeça no lugar. Se o alvo estiver por perto, vou precisar do seu poder para localizar a posição dele.",
  ui_story_5057_50570901_38_dialog_content = "Aja naturalmente... Se ele perceber que foi descoberto, pessoas inocentes podem se machucar.",
  ui_story_5057_50570901_39_dialog_content = "Você só precisa se concentrar na tarefa em questão. Aqui.",
  ui_story_5057_50570901_40_dialog_content = "O que é isso?",
  ui_story_5057_50570901_41_dialog_content = "Protetor solar.",
  ui_story_5057_50570901_42_dialog_content = "Eu sei que é protetor solar... Mas, hã...",
  ui_story_5057_50570901_43_dialog_content = "Você quer agir de forma estranha e atrair atenção indesejada?",
  ui_story_5057_50570901_44_dialog_content = "Claro que não!",
  ui_story_5057_50570901_45_dialog_content = "Você quer que eu fique com uma queimadura de sol, então?",
  ui_story_5057_50570901_46_dialog_content = "<color=#e8d9bb>Por um breve momento, fico encantado com as costas de Paloma, tão brancas quanto a neve, parecendo irradiar um brilho cintilante à luz do sol.</color>",
  ui_story_5057_50570901_47_dialog_content = "Em primeiro lugar, pagarei a você o que já combinamos. Colocar protetor solar em mim não vai te dar um bônus.",
  ui_story_5057_50570901_48_dialog_content = "Não foi o que eu quis dizer...! Eu nunca fiz isso antes, então...",
  ui_story_5057_50570901_49_dialog_content = "Então, você está surtando?",
  ui_story_5057_50570901_50_dialog_content = "Sem chance! Vou esfregar isso em você!",
  ui_story_5057_50570901_51_dialog_content = "Lá vamos nós, assim é melhor.",
  ui_story_5057_50570901_52_dialog_content = "Por que você está tremendo? Seja sério e certifique-se de aplicar uniformemente.",
  ui_story_5057_50570901_53_dialog_content = "Está bem, está bem!",
  ui_story_5057_50570901_54_dialog_content = "Enquanto isso, mantenha seus olhos naquela direção para qualquer coisa suspeita.",
  ui_story_5057_50570901_55_dialog_content = "Sim!",
  ui_story_5057_50570901_56_dialog_content = "(Uau, meu coração está batendo a mil por hora.)",
  ui_story_5057_50570901_57_dialog_content = "Por que você está parando—",
  ui_story_5057_50570901_58_dialog_content = "Acho que tem alguém suspeito ali!",
  ui_story_5057_50570901_59_dialog_content = "É ele. Eu consegui.",
  ui_story_5057_50570901_60_dialog_content = "<color=#e8d9bb>EveMesmo que Paloma e eu tenhamos capturado o mascate de informações, minhas mãos ainda estão tremendo.</color>",
  ui_story_5057_50570902_1_dialog_content = "Vou hospedar o Paloma novamente hoje?",
  ui_story_5057_50570902_2_dialog_content = "Depois do que aconteceu da última vez, acho que não consigo encarar ela.",
  ui_story_5057_50570902_3_dialog_content = "Que dilema... Ainda consigo ver quando fecho meus olhos.",
  ui_story_5057_50570902_4_dialog_content = "Oi, PlayerName, trouxe uma bebida para você.",
  ui_story_5057_50570902_5_dialog_content = "Não, não, pare de imaginar.",
  ui_story_5057_50570902_6_dialog_content = "...",
  ui_story_5057_50570902_7_dialog_content = "PlayerName！",
  ui_story_5057_50570902_8_dialog_content = "Olá, Paloma!",
  ui_story_5057_50570902_9_dialog_content = "O que você está fazendo aí sonhando acordado de novo? Cuidado ou alguns malvados vão te sequestrar e te vender na loja de animais!",
  ui_story_5057_50570902_10_dialog_content = "Não pode ser tão ruim assim, pode? Obrigado pela bebida... *glup*",
  ui_story_5057_50570902_11_dialog_content = "Eu coloquei sedativos nele.",
  ui_story_5057_50570902_12_dialog_content = "<size=50>Pfft—!</size>",
  ui_story_5057_50570902_13_dialog_content = "Hahaha, só brincando.",
  ui_story_5057_50570902_14_dialog_content = "Isso não é engraçado...",
  ui_story_5057_50570902_15_dialog_content = "Aham... Então, sobre a última vez... Eu não quis dizer...",
  ui_story_5057_50570902_16_dialog_content = "Última vez? Como assim?",
  ui_story_5057_50570902_17_dialog_content = "Sabe, quando eu te ajudei a pegar aquele cara...",
  ui_story_5057_50570902_18_dialog_content = "Ah, você está falando de passar protetor solar em mim—",
  ui_story_5057_50570902_19_dialog_content = "Não tão alto, por favor!",
  ui_story_5057_50570902_20_dialog_content = "<color=#e8d9bb>Paloma arqueia uma sobrancelha, olhando para mim com um brilho brincalhão nos olhos.</color>",
  ui_story_5057_50570902_21_dialog_content = "Você acha que eu ficaria bravo com você por isso?",
  ui_story_5057_50570902_22_dialog_content = "Não... Porque... Eu...",
  ui_story_5057_50570902_23_dialog_content = "Você está se desculpando por se sentir estranho ao passar protetor solar, ou pelo ato de aplicar protetor solar em mim?",
  ui_story_5057_50570902_24_dialog_content = "Se for a última opção, você pode parar, pois eu pedi para você fazer isso.",
  ui_story_5057_50570902_25_dialog_content = "Heh, acho que você ainda é inocente no coração, PlayerName.",
  ui_story_5057_50570902_26_dialog_content = "Se coisas pequenas como essa te fazem entrar em pânico, o que acontece se tiver que ser mais íntimo da próxima vez?",
  ui_story_5057_50570902_27_dialog_content = "Tal como algo mais privado?",
  ui_story_5057_50570902_28_dialog_content = "Eu acho que não haverá uma próxima vez...",
  ui_story_5057_50570902_29_dialog_content = "E você não me pediria para fazer algo mais íntimo, pediria?",
  ui_story_5057_50570902_30_dialog_content = "Ah? Então qual é a sua ideia de \"intimidade\"?",
  ui_story_5057_50570902_31_dialog_content = "S-Sabe, isso!",
  ui_story_5057_50570902_32_dialog_content = "Hã?",
  ui_story_5057_50570902_33_option_content = "Você me obrigaria a...",
  ui_story_5057_50570902_34_dialog_content = "Hahaha, nunca vou deixar você ir longe demais.",
  ui_story_5057_50570902_35_option_content = "Eu... Eu não sei!",
  ui_story_5057_50570902_36_dialog_content = "<color=#e8d9bb>Paloma bagunça meu cabelo com a mão.</color>",
  ui_story_5057_50570902_37_dialog_content = "O trabalho seria um fracasso épico se você desmaiasse de modéstia!",
  ui_story_5057_50570902_38_dialog_content = "Oh...",
  ui_story_5057_50570902_39_dialog_content = "Sinceramente, porém, eu não me importaria se o trabalho exigisse isso.",
  ui_story_5057_50570902_40_dialog_content = "É apenas um trabalho. Não me diga que vai levar isso a sério, PlayerName.",
  ui_story_5057_50570902_41_dialog_content = "Bom...",
  ui_story_5057_50570902_42_dialog_content = "Ah, para evitar possíveis problemas durante um trabalho e a necessidade de descontar seu salário...",
  ui_story_5057_50570902_43_dialog_content = "Vamos ensaiar para que você se acostume com isso.",
  ui_story_5057_50570902_44_option_content = "O-O que?",
  ui_story_5057_50570902_45_dialog_content = "Estou brincando. Você achou que eu estava falando sério?",
  ui_story_5057_50570902_46_dialog_content = "Você é realmente inocente!",
  ui_story_5057_50570902_47_dialog_content = "Eca-!",
  ui_story_5057_50570902_48_option_content = "Por favor, pare com isso!",
  ui_story_5057_50570902_49_dialog_content = "Hahaha, desculpe.",
  ui_story_5057_50570902_50_dialog_content = "Hmm, e agora?",
  ui_story_5057_50570902_51_dialog_content = "Você não parece satisfeito.",
  ui_story_5057_50570902_52_dialog_content = "Está fazendo birra porque eu te provoquei?",
  ui_story_5057_50570902_53_dialog_content = "E que tal lutar comigo, então?",
  ui_story_5057_50570902_54_dialog_content = "Lutar com você?",
  ui_story_5057_50570902_55_dialog_content = "Isso mesmo. Se você ganhar, farei tudo o que você quiser por um dia. Claro, isso inclui o que mencionei antes.",
  ui_story_5057_50570902_56_dialog_content = "Se você perder, vai trabalhar comigo no Café das Irmãs, e eu fico com o seu salário também.",
  ui_story_5057_50570902_57_dialog_content = "Espere um minuto... O que é um Café de Freiras? Isso parece estranho!",
  ui_story_5057_50570902_58_dialog_content = "É uma longa história. Era uma noite fria.",
  ui_story_5057_50570902_59_dialog_content = "Ao atravessar uma rua em Umbraton, o vento frio devastou meu corpo.",
  ui_story_5057_50570902_60_dialog_content = "Eu estava me esforçando para mastigar e engolir a última mordida do meu último bolinho de arroz.",
  ui_story_5057_50570902_61_dialog_content = "Como você chegou a esse ponto...",
  ui_story_5057_50570902_62_dialog_content = "A vingança exige grandes capitais, PlayerName.",
  ui_story_5057_50570902_63_dialog_content = "Uma freira gentil me apresentou e conseguiu um emprego de meio período em uma cafeteria.",
  ui_story_5057_50570902_64_dialog_content = "Aqueles foram dias felizes. Eu até esqueci da vingança, até que um dia.",
  ui_story_5057_50570902_65_dialog_content = "<size=50>Ah—por favor, pare com isso, senhor.</size>",
  ui_story_5057_50570902_66_dialog_content = "Tsc, tsc, tsc... você percebe quantas maneiras o Verso 50 no Capítulo 11, Volume 7 dos Princípios da Igreja da Noite Clara pode ser interpretado?",
  ui_story_5057_50570902_67_dialog_content = "P-Por favor, solte-me...",
  ui_story_5057_50570902_68_dialog_content = "Por favor, pare com isso, senhor.",
  ui_story_5057_50570902_69_dialog_content = "Ah, é você.",
  ui_story_5057_50570902_70_dialog_content = "Sou eu, Mirren. Gravei tudo o que você acabou de fazer.",
  ui_story_5057_50570902_71_dialog_content = "Dê-me dez bilhões de Noitium ou sofra!",
  ui_story_5057_50570902_72_dialog_content = "O quê? Não posso simplesmente me desculpar?",
  ui_story_5057_50570902_73_dialog_content = "Isso não é uma opção. Eu aposto minha vida desde a infância até agora em buscar vingança contra você. Como um pedido de desculpas poderia ser suficiente?",
  ui_story_5057_50570902_74_dialog_content = "Droga, estou fora daqui!",
  ui_story_5057_50570902_75_dialog_content = "Você me salvou, Paloma... Agora sou seu para sempre...",
  ui_story_5057_50570902_76_dialog_content = "Obrigado, mas não obrigado.",
  ui_story_5057_50570902_77_dialog_content = "Eu não preciso de um Celestita. O que eu preciso é de um carrasco que possa me acompanhar na minha vingança.",
  ui_story_5057_50570902_78_dialog_content = "Por que eu e Mirren estamos na história?",
  ui_story_5057_50570902_79_dialog_content = "É assim que funciona. De qualquer forma, você vai trabalhar comigo se perder.",
  ui_story_5057_50570902_X80_dialog_content = "<color=#e8d9bb>Paloma lançou um desafio de pesca, e eu fiquei tipo, \"Ah, eu vou ganhar isso com certeza!\"</color>",
  ui_story_5057_50570902_80_dialog_content = "<color=#e8d9bb>Então, para me familiarizar com as coisas no Habit Café, comecei a memorizar os princípios da Igreja da Lumópolis.</color>",
  ui_story_5057_50571001_1_dialog_content = "Bom dia, PlayerName!",
  ui_story_5057_50571001_2_dialog_content = "Bom dia, Vice.",
  ui_story_5057_50571001_3_dialog_content = "Para onde você está indo com toda essa bagagem?",
  ui_story_5057_50571001_4_dialog_content = "Estas são algumas ferramentas para reparo e manutenção.",
  ui_story_5057_50571001_5_dialog_content = "Lorelei me disse que alguns brinquedos não estavam funcionando bem e pediu para consertá-los.",
  ui_story_5057_50571001_6_dialog_content = "Entendi, mas não seria melhor deixar para os caras da Chave Rediesel?",
  ui_story_5057_50571001_7_dialog_content = "Sim, mas eles partiram de carro para sei-lá-onde há alguns dias.",
  ui_story_5057_50571001_8_dialog_content = "Eles não deram notícias desde então. Estou adivinhando que eles...",
  ui_story_5057_50571001_9_dialog_content = "Eu posso praticamente adivinhar o que você está adivinhando.",
  ui_story_5057_50571001_10_dialog_content = "Uhum. Lorelei também fez uma oferta muito generosa!",
  ui_story_5057_50571001_11_dialog_content = "Vamos empatar o mês depois disso!",
  ui_story_5057_50571001_12_dialog_content = "Você tem planos para o dia, PlayerName?",
  ui_story_5057_50571001_13_dialog_content = "Hum... (Não tem como eu dizer que quero ir tomar sol e pescar...)",
  ui_story_5057_50571001_14_dialog_content = "Na verdade, não, então por que eu não vou com você?",
  ui_story_5057_50571001_15_dialog_content = "Vou ser seu ajudante do dia!",
  ui_story_5057_50571001_16_dialog_content = "Ótimo, vou contar com você então!",
  ui_story_5057_50571001_17_dialog_content = "Claro. Deixe-me ajudar você a carregar as ferramentas!",
  ui_story_5057_50571001_18_dialog_content = "A estrutura inteira parece estável o suficiente, então é apenas este parafuso de backup que ficou um pouco solto.",
  ui_story_5057_50571001_19_dialog_content = "Ajude-me a apertar o parafuso, PlayerName.",
  ui_story_5057_50571001_20_dialog_content = "Pode deixar!",
  ui_story_5057_50571001_21_dialog_content = "Tá bom. Aqui vamos nós!",
  ui_story_5057_50571001_22_dialog_content = "Hiya!",
  ui_story_5057_50571001_23_dialog_content = "Por favor, me passe isso.",
  ui_story_5057_50571001_24_dialog_content = "Você quer dizer o lubrificante? Aqui, tudo pronto para ir!",
  ui_story_5057_50571001_25_dialog_content = "Você me entende muito bem, PlayerName.",
  ui_story_5057_50571001_26_dialog_content = "Excelente no que diz respeito a um ajudante.",
  ui_story_5057_50571001_27_dialog_content = "É claro. Estamos juntos há tanto tempo que temos uma ótima química.",
  ui_story_5057_50571001_28_dialog_content = "Ok, tudo feito.",
  ui_story_5057_50571001_29_dialog_content = "Este é o último lugar para verificar.",
  ui_story_5057_50571001_30_dialog_content = "Podemos voltar depois de arrumar as ferramentas.",
  ui_story_5057_50571001_31_dialog_content = "Maravilhoso!",
  ui_story_5057_50571001_32_dialog_content = "Essa manutenção é ainda mais suave do que eu imaginava.",
  ui_story_5057_50571001_33_dialog_content = "E eu não esperava que os passeios projetados pela Rediesel Wrench tivessem uma certa qualidade estética.",
  ui_story_5057_50571001_34_dialog_content = "A estrutura pode ser simples, mas a engenhosidade empregada nela permitiu que fosse executada com um baixo custo de manutenção.",
  ui_story_5057_50571001_35_dialog_content = "Afinal, há muitos mecânicos incríveis no Rediesel Wrench.",
  ui_story_5057_50571001_36_dialog_content = "A capacidade de fazer uso dos recursos disponíveis é provavelmente uma das razões pelas quais eles são tão bons em sobrevivência.",
  ui_story_5057_50571001_37_dialog_content = "Hum, aprendi muito com eles hoje. Illumina poderia tirar uma página ou duas de seu livro.",
  ui_story_5057_50571001_38_dialog_content = "Esse é o Vice que eu conheço, sempre pensando em aprender e absorver algo novo!",
  ui_story_5057_50571001_39_dialog_content = "Por que o elogio repentino?",
  ui_story_5057_50571001_40_dialog_content = "Como seu amigo, é claro que preciso continuar aprendendo e ficando mais forte para proteger você e Soroz.",
  ui_story_5057_50571001_41_option_content = "Estou emocionado...",
  ui_story_5057_50571001_42_option_content = "Vice...",
  ui_story_5057_50571001_43_dialog_content = "Ei, por que você está chorando?",
  ui_story_5057_50571001_44_dialog_content = "Ah, eu só fiquei emocionado, só isso.",
  ui_story_5057_50571001_45_dialog_content = "Pensando bem, a primeira vez que te conheci foi quando você acidentalmente destruiu o chão...",
  ui_story_5057_50571001_46_dialog_content = "Agora você se tornou tão confiável...!",
  ui_story_5057_50571001_47_dialog_content = "Pare aí mesmo! Não ouse mencionar aquele constrangimento de novo!",
  ui_story_5057_50571001_48_dialog_content = "Você está exagerando demais, PlayerName. Todo mundo está melhorando constantemente, e isso inclui você.",
  ui_story_5057_50571001_49_dialog_content = "Eu cresci? Não pareceu mesmo...",
  ui_story_5057_50571001_50_dialog_content = "Esse é o pensamento errado e fedorento. Eu vi você melhorar com meus próprios olhos.",
  ui_story_5057_50571001_51_dialog_content = "Ao ponto que não consigo nem imaginar sem você por perto...",
  ui_story_5057_50571001_52_dialog_content = "Gruau...",
  ui_story_5057_50571001_53_dialog_content = "Desculpe, fui eu! Eu estava com pressa para vir ajudar você, pulei o café da manhã!",
  ui_story_5057_50571001_54_dialog_content = "Deixe-me ver... Realmente está bem tarde!",
  ui_story_5057_50571001_55_dialog_content = "Vem almoçar comigo, PlayerName!",
  ui_story_5057_50571001_56_dialog_content = "<size=30>Uh, não pode ser o que Vice fez, pode?</size>",
  ui_story_5057_50571001_57_dialog_content = "<size=30>Eu só me lembrei dela perguntando onde ela poderia cozinhar ontem...</size>",
  ui_story_5057_50571001_58_dialog_content = "Ei, o que você está resmungando?",
  ui_story_5057_50571001_59_dialog_content = "Não está com fome? Não quer comer comigo?",
  ui_story_5057_50571001_60_dialog_content = "(Oh-oh, já é hora de decidir?)",
  ui_story_5057_50571001_61_dialog_content = "eu, eh...",
  ui_story_5057_50571001_62_option_content = "Mal posso esperar para experimentar o que você fez, Vice!",
  ui_story_5057_50571001_63_dialog_content = "<size=30>Dado que eu não recusei da primeira vez que ela cozinhou algo...</size>",
  ui_story_5057_50571001_64_dialog_content = "<size=30>É minha responsabilidade comer todas as refeições Vice feitas!</size>",
  ui_story_5057_50571001_65_dialog_content = "Agradeço por sussurrar o incentivo, mas eu não fiz nenhum almoço hoje.",
  ui_story_5057_50571001_66_dialog_content = "Já que acordei cedo de manhã para reunir ferramentas, merecemos nos esbanjar!",
  ui_story_5057_50571001_67_option_content = "Hoje é por minha conta!",
  ui_story_5057_50571001_68_dialog_content = "Este é um parque, você sabe! Deixe-me te levar ao restaurante que mencionei da última vez!",
  ui_story_5057_50571001_69_dialog_content = "Isso parece bom... Mas você tem o dinheiro, PlayerName?",
  ui_story_5057_50571001_70_dialog_content = "Hã, bom... Que tal me dar um adiantamento?",
  ui_story_5057_50571001_71_dialog_content = "Eu sabia!",
  ui_story_5057_50571001_72_dialog_content = "Vamos lá, eu estava planejando usar o pagamento deste trabalho de manutenção para esbanjar com você de qualquer maneira.",
  ui_story_5057_50571001_73_dialog_content = "<color=#e8d9bb>Então Vice e eu passamos um dia alegre juntos, e ela parece incrivelmente feliz. Isso é fantástico!</color>",
  ui_story_5057_50571002_1_dialog_content = "Aqui estamos!",
  ui_story_5057_50571002_2_dialog_content = "Bela vista. Seria ótimo para acampar.",
  ui_story_5057_50571002_3_dialog_content = "Ajude-me, V-Vice... Meus joelhos estão cedendo... com todo esse equipamento...",
  ui_story_5057_50571002_4_dialog_content = "PlayerName！",
  ui_story_5057_50571002_5_dialog_content = "Vocês estão bem? Venham sentar e relaxar.",
  ui_story_5057_50571002_6_dialog_content = "Estou bem... Quer dizer, fui eu quem te pediu para me ensinar sobre sobrevivência na natureza, afinal...",
  ui_story_5057_50571002_7_dialog_content = "Então eu devo me esforçar para chegar até o fim...!",
  ui_story_5057_50571002_8_dialog_content = "Mas a carga é mesmo... muito pesada!",
  ui_story_5057_50571002_9_dialog_content = "Ahaha, me desculpe por isso.",
  ui_story_5057_50571002_10_dialog_content = "Ele continha dez dias de rações e todo o complemento para o treinamento de sobrevivência na natureza para iniciantes da Illumina, então provavelmente é um pouco pesado.",
  ui_story_5057_50571002_11_dialog_content = "P-Por que dez dias? Isso é realmente necessário?",
  ui_story_5057_50571002_12_dialog_content = "Bem, como posso explicar...",
  ui_story_5057_50571002_13_dialog_content = "Mayfoi a determinação em seus olhos ontem à noite que alimentou o espírito de luta em mim.",
  ui_story_5057_50571002_14_dialog_content = "Foi você quem disse: \"Por favor, treine-me, tenente Vice!\"",
  ui_story_5057_50571002_15_dialog_content = "Eu estava pensando sobre suas limitações físicas enquanto tirava e colocava as rações repetidamente.",
  ui_story_5057_50571002_16_dialog_content = "Considerando que estamos aprimorando seu corpo e vontade ao máximo, decidi definir a quantidade para dez dias.",
  ui_story_5057_50571002_17_dialog_content = "No entanto, eu acredito que você poderia fazer isso, e você fez isso!",
  ui_story_5057_50571002_18_dialog_content = "Desculpe por você ter uma expectativa tão alta de mim.",
  ui_story_5057_50571002_19_dialog_content = "Felizmente, consegui carregar tudo até aqui e não te decepcionei.",
  ui_story_5057_50571002_20_dialog_content = "Sim, você se saiu bem, PlayerName.",
  ui_story_5057_50571002_21_dialog_content = "Caminhar tão longe com essa carga é louvável para um novato da Illumina.",
  ui_story_5057_50571002_22_dialog_content = "Sério?",
  ui_story_5057_50571002_23_dialog_content = "S-Sim...",
  ui_story_5057_50571002_24_dialog_content = "...",
  ui_story_5057_50571002_25_dialog_content = "Ah, você deve estar exausto, PlayerName. Quer fazer uma pausa?",
  ui_story_5057_50571002_26_dialog_content = "Coloque a mochila no chão e deixe-me massagear seus ombros.",
  ui_story_5057_50571002_27_dialog_content = "Ou devemos montar a barraca primeiro?",
  ui_story_5057_50571002_28_option_content = "Eu preciso dos dois!",
  ui_story_5057_50571002_29_dialog_content = "O que vou fazer com você, PlayerName...",
  ui_story_5057_50571002_30_dialog_content = "Tudo bem, vamos chamar isso de recomp. pelo seu árduo trabalho!",
  ui_story_5057_50571002_31_option_content = "Monte a barraca primeiro.",
  ui_story_5057_50571002_32_dialog_content = "Sim, é melhor ter um lugar para descansar.",
  ui_story_5057_50571002_33_dialog_content = "Vou te ensinar como colocá-lo, PlayerName.",
  ui_story_5057_50571002_34_dialog_content = "Apenas coloque as estacas aqui.",
  ui_story_5057_50571002_35_dialog_content = "Venha, PlayerName, finque as estacas no chão com toda a sua força.",
  ui_story_5057_50571002_36_dialog_content = "Certifique-se de que eles entrem profundamente e com segurança.",
  ui_story_5057_50571002_37_dialog_content = "Entendido! Deixa comigo!",
  ui_story_5057_50571002_38_dialog_content = "Iiáaa!",
  ui_story_5057_50571002_39_dialog_content = "Hiya!",
  ui_story_5057_50571002_40_dialog_content = "Isso serve. Agora coloque a lona sobre a barraca. Eu já cobri o chão.",
  ui_story_5057_50571002_41_dialog_content = "Lembre-se de cobrir o chão primeiro na próxima vez, PlayerName.",
  ui_story_5057_50571002_42_dialog_content = "Sim!",
  ui_story_5057_50571002_43_dialog_content = "Quando você terminar, teste para ver se aguenta.",
  ui_story_5057_50571002_44_dialog_content = "A barraca está concluída se não houver problema.",
  ui_story_5057_50571002_45_dialog_content = "Deixe-me ver a barraca que você montou...",
  ui_story_5057_50571002_46_dialog_content = "Muito resistente. Você tiraria 80 ou mais em um teste.",
  ui_story_5057_50571002_47_dialog_content = "Eu já te ensinei como ler o mapa e a bússola, além de explicar as etapas essenciais do primeiro socorro.",
  ui_story_5057_50571002_48_dialog_content = "Sim, eu memorizei isso o máximo que pude.",
  ui_story_5057_50571002_49_dialog_content = "A seguir vem a conservação de comida e água, depois disso, você terá mais de 70% de chance de sobreviver na natureza.",
  ui_story_5057_50571002_50_dialog_content = "Tenho a sensação de que este Vice aqui e agora salvou o futuro eu novamente.",
  ui_story_5057_50571002_51_dialog_content = "A barraca parece agradável, como se eu tivesse acabado de construir uma casa para Vice e eu mesmo.",
  ui_story_5057_50571002_52_dialog_content = "Ah é? Então isso significa que somos família, PlayerName?",
  ui_story_5057_50571002_53_dialog_content = "Claro que você é da família, Vice.",
  ui_story_5057_50571002_54_dialog_content = "M-Mesmo...?",
  ui_story_5057_50571002_55_dialog_content = "Na verdade, eu também me sinto assim.",
  ui_story_5057_50571002_56_dialog_content = "Sim, é realmente legal sair com a família.",
  ui_story_5057_50571002_57_dialog_content = "Fico muito feliz quando estou com você.",
  ui_story_5057_50571002_58_dialog_content = "Ah, para agradecer pela massagem e por me ensinar a montar uma barraca, vou cozinhar hoje à noite!",
  ui_story_5057_50571002_59_dialog_content = "Eu implorei a Gram para me mostrar como tornar as rações mais saborosas.",
  ui_story_5057_50571002_60_dialog_content = "Tudo bem, dessa vez vou depender de você, PlayerName.",
  ui_story_5057_50571002_61_dialog_content = "Comendo as deliciosas porções que você cozinha enquanto aprecia a paisagem natural...",
  ui_story_5057_50571002_62_dialog_content = "Todo o cansaço de pegar um trabalho após o outro simplesmente desaparece!",
  ui_story_5057_50571002_63_dialog_content = "Acampar é ótimo, entendi.",
  ui_story_5057_50571002_64_dialog_content = "Deixe para mim! Vou começar o fogo agora!",
  ui_story_5057_50571002_65_dialog_content = "<color=#e8d9bb>Então Vice e eu nos fartamos tanto que passamos a noite deitados, admirando as estrelas até tarde, antes de finalmente voltarmos para a barraca.</color>",
  ui_story_5057_50571101_1_dialog_content = "Desculpe, me atrasei!",
  ui_story_5057_50571101_2_dialog_content = "Sem preocupações, você ainda tem dois minutos. Eu também acabei de chegar.",
  ui_story_5057_50571101_3_dialog_content = "De qualquer forma, por que você está vestido assim?",
  ui_story_5057_50571101_4_dialog_content = "Ah, é um macacão de manutenção que peguei emprestado de Lorelei.",
  ui_story_5057_50571101_5_dialog_content = "Já que é difícil lavar as manchas de gordura das roupas comuns.",
  ui_story_5057_50571101_6_dialog_content = "Mas me lembro de você pedindo vários conjuntos do mesmo traje depois.",
  ui_story_5057_50571101_7_dialog_content = "Ah, foi originalmente dado a mim por Soroz, uma das raras fantasias que me servem.",
  ui_story_5057_50571101_8_dialog_content = "Antes disso... Como posso explicar... Às vezes, eu ficava sem roupas.",
  ui_story_5057_50571101_9_dialog_content = "Entendi. Posso começar a entender por que você é tão sentimental em relação a isso.",
  ui_story_5057_50571101_10_dialog_content = "Mas é apenas um... Que tal eu te levar para comprar dois novos conjuntos, feitos sob medida, em Lumópolis na próxima vez?",
  ui_story_5057_50571101_11_dialog_content = "Posso te apresentar ao alfaiate. O Senhor da Cidade disse que ele tem servido minha família por mais de trinta anos.",
  ui_story_5057_50571101_12_dialog_content = "Atendendo sua família? Isso não o tornaria um alfaiate incrível?",
  ui_story_5057_50571101_13_dialog_content = "Com certeza, absolutamente à altura dos melhores designers da Cidade do Porto.",
  ui_story_5057_50571101_14_dialog_content = "Isso também pode ser muito caro...",
  ui_story_5057_50571101_15_dialog_content = "Eu também não tenho certeza disso.",
  ui_story_5057_50571101_16_dialog_content = "Mas acredito que há espaço no orçamento de Lumópolis dedicado aos trajes do Senhor da Cidade e sua família.",
  ui_story_5057_50571101_17_dialog_content = "Um estilo personalizado para se ajustar emana sentimentos completamente diferentes.",
  ui_story_5057_50571101_18_dialog_content = "É mesmo? Não é à toa que eu achei que todas as suas roupas te caíam perfeitamente...",
  ui_story_5057_50571101_19_dialog_content = "Você parecia tão graciosa e bonita quanto a luz do luar...",
  ui_story_5057_50571101_20_dialog_content = "Não pude deixar de me lembrar de um ditado Longzhou que li...",
  ui_story_5057_50571101_21_dialog_content = "Mostra-se de uma maneira deslumbrante, apenas para se esconder na nuvem em breve.",
  ui_story_5057_50571101_22_dialog_content = "Acho que isso descreveu bem.",
  ui_story_5057_50571101_23_dialog_content = "Ahem, obrigado pelo elogio, mas por favor pare.",
  ui_story_5057_50571101_24_dialog_content = "Ah, perdão. Foi um exagero.",
  ui_story_5057_50571101_25_dialog_content = "O quê?",
  ui_story_5057_50571101_26_dialog_content = "Ah, quer dizer... Enfim...",
  ui_story_5057_50571101_27_dialog_content = "Hehehe... Está bem.",
  ui_story_5057_50571101_28_dialog_content = "Não tem trabalho para fazer? Não deveríamos parar de conversar?",
  ui_story_5057_50571101_29_dialog_content = "Isso mesmo, eu preciso consertar o Dragão da Noite Clara!",
  ui_story_5057_50571101_30_dialog_content = "Uau, é tão alto aqui... Parece que estou de pé no céu.",
  ui_story_5057_50571101_31_dialog_content = "É realmente difícil ganhar dinheiro às vezes.",
  ui_story_5057_50571101_32_dialog_content = "O freio do terceiro carrinho está quebrado, PlayerName.",
  ui_story_5057_50571101_33_dialog_content = "Basta trocar que deve funcionar.",
  ui_story_5057_50571101_34_dialog_content = "Tudo bem, estarei aí já—!",
  ui_story_5057_50571101_35_dialog_content = "Cuidado, cuidado...",
  ui_story_5057_50571101_36_dialog_content = "Não olhe para baixo...",
  ui_story_5057_50571101_37_dialog_content = "Pegue minha mão, PlayerName.",
  ui_story_5057_50571101_38_dialog_content = "Claro!",
  ui_story_5057_50571101_39_dialog_content = "Você teve uma experiência difícil com o passeio da última vez, mas agora não tem medo de altura.",
  ui_story_5057_50571101_40_dialog_content = "Estar lá no alto e surfar são duas coisas diferentes... O último é um inferno.",
  ui_story_5057_50571101_41_dialog_content = "Tudo bem, vou cuidar do teste de estresse depois.",
  ui_story_5057_50571101_42_dialog_content = "Estou trocando o disco de freio.",
  ui_story_5057_50571101_43_dialog_content = "<color=#e8d9bb>Alguns minutos depois</color>",
  ui_story_5057_50571101_44_dialog_content = "Isso deve resolver.",
  ui_story_5057_50571101_45_dialog_content = "Vou entrar para um teste de pilotagem. Basta controlar com este dispositivo aqui, Carleen.",
  ui_story_5057_50571101_46_dialog_content = "Tem certeza? Mayeu deveria ser o único a cavalgar.",
  ui_story_5057_50571101_47_dialog_content = "Não se preocupe, se algo acontecer, eu vou lidar com isso.",
  ui_story_5057_50571101_48_dialog_content = "Tudo bem, então tome cuidado.",
  ui_story_5057_50571101_49_dialog_content = "Estou preso... Tudo bem, deixa rolar!",
  ui_story_5057_50571101_50_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5057_50571101_51_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5057_50571101_52_dialog_content = "Uau, essa montanha-russa é realmente um demônio da velocidade.",
  ui_story_5057_50571101_53_dialog_content = "Espere, como assim está indo muito mais rápido do que o normal?",
  ui_story_5057_50571101_54_dialog_content = "<color=#e8d9bb>Clam, clang!</color>",
  ui_story_5057_50571101_55_dialog_content = "Que diabos...!",
  ui_story_5057_50571101_56_dialog_content = "Pare o passeio, Carleen!",
  ui_story_5057_50571101_57_dialog_content = "<color=#e8d9bb>Rangidos—</color>",
  ui_story_5057_50571101_58_dialog_content = "O freio foi acionado!",
  ui_story_5057_50571101_59_dialog_content = "Consigo ver o quarto carrinho balançando daqui!",
  ui_story_5057_50571101_60_dialog_content = "Entendi! Deve ser um problema com o conector!",
  ui_story_5057_50571101_61_dialog_content = "Por que você desafivelou, PlayerName?!",
  ui_story_5057_50571101_62_dialog_content = "Eu tenho que consertar isso agora, ou a montanha-russa inteira pode sair dos trilhos e machucar as pessoas no chão!",
  ui_story_5057_50571101_63_dialog_content = "É muito perigoso!",
  ui_story_5057_50571101_64_dialog_content = "Sem problemas, me dê um segundo para diminuir a velocidade e podemos parar completamente...",
  ui_story_5057_50571101_65_dialog_content = "<color=#e8d9bb>Clique-</color>",
  ui_story_5057_50571101_66_dialog_content = "Consegui!",
  ui_story_5057_50571101_67_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5057_50571101_68_dialog_content = "PlayerName!",
  ui_story_5057_50571101_69_dialog_content = "O-O que está acontecendo, eu saí voando do brinquedo?",
  ui_story_5057_50571101_70_dialog_content = "Estou caindo rápido... Será essa a última coisa que vejo, para sempre?",
  ui_story_5057_50571101_71_dialog_content = "Segura a minha mão, PlayerName!",
  ui_story_5057_50571101_72_dialog_content = "Carleen? Claro!",
  ui_story_5057_50571101_73_dialog_content = "Ufa... Tenho sorte de você estar por perto, Carleen.",
  ui_story_5057_50571101_74_dialog_content = "Você me salvou novamente. EveQuando o cabo de segurança se rompeu. Que vergonhoso...",
  ui_story_5057_50571101_75_dialog_content = "Claro que vou ajudar assim que tiver a chance quando você estiver em perigo, PlayerName.",
  ui_story_5057_50571101_76_dialog_content = "Somos amigos próximos, então você não me deve nada.",
  ui_story_5057_50571101_77_dialog_content = "Tudo bem, mas ainda me sinto péssimo com isso.",
  ui_story_5057_50571101_78_dialog_content = "O que há para se sentir péssimo?",
  ui_story_5057_50571101_79_option_content = "Que eu continuo precisando ser salvo",
  ui_story_5057_50571101_80_option_content = "Gostaria de salvar Carleen também",
  ui_story_5057_50571101_81_dialog_content = "Eu adoraria ter o poder de proteger e salvar você, Carleen.",
  ui_story_5057_50571101_82_dialog_content = "Entendi.",
  ui_story_5057_50571101_83_dialog_content = "Mas você não me salvou, outras pessoas e até mesmo Lumópolis, várias vezes à sua maneira?",
  ui_story_5057_50571101_84_dialog_content = "Bem, mas não é a mesma coisa.",
  ui_story_5057_50571101_85_dialog_content = "É tudo a mesma coisa para mim.",
  ui_story_5057_50571101_86_dialog_content = "Para mim, você tem cuidado de mim à sua própria maneira e com esforço.",
  ui_story_5057_50571101_87_dialog_content = "Se você está preocupado com isso, por que não me convida para tomar aquele sorvete ali?",
  ui_story_5057_50571101_88_dialog_content = "O quê? É claro... Ei, espera aí, meus joelhos ainda estão tremendo...",
  ui_story_5057_50571101_89_dialog_content = "<color=#e8d9bb>Então Carleen e eu comemos muito sorvete juntos, o que me deixou com uma dor de cabeça intensa durante a noite.</color>",
  ui_story_5057_50571102_1_dialog_content = "Não é um problema, não é um problema desta vez com certeza...",
  ui_story_5057_50571102_2_dialog_content = "Afinal, sou um nobre de Lumópolis.",
  ui_story_5057_50571102_3_dialog_content = "Eu sou Carleen de Schwartz, filha de Daniel de Schwartz.",
  ui_story_5057_50571102_4_dialog_content = "Independentemente do perigo, vou superar com minha espada afiada.",
  ui_story_5057_50571102_5_dialog_content = "Independentemente das dificuldades, suportarei com honra.",
  ui_story_5057_50571102_6_dialog_content = "C-Carleen?",
  ui_story_5057_50571102_7_dialog_content = "Por favor, conceda-me a serenidade para permanecer calmo no caos e mostrar misericórdia no ódio.",
  ui_story_5057_50571102_8_dialog_content = "Conceda-me a fé para permanecer resoluto na incerteza, indomável na agitação.",
  ui_story_5057_50571102_9_dialog_content = "Conceda-me a resiliência para permanecer firme diante das adversidades, forte sob pressão.",
  ui_story_5057_50571102_10_dialog_content = "E a gentileza de permanecer compassivo em meio à apatia, esperançoso no desespero.",
  ui_story_5057_50571102_11_dialog_content = "Ah, Carleen?",
  ui_story_5057_50571102_12_dialog_content = "Ufa...",
  ui_story_5057_50571102_13_dialog_content = "Você não parece tão bem... Que tal esquecermos?",
  ui_story_5057_50571102_14_dialog_content = "Não é necessário experimentar todos os brinquedos radicais.",
  ui_story_5057_50571102_15_dialog_content = "Há outras atrações seguras, mas ainda muito divertidas!",
  ui_story_5057_50571102_16_dialog_content = "Por exemplo, aquele trenzinho fofo bem ali. Podemos pegá-lo e fazer um tour por todo o Denuo.",
  ui_story_5057_50571102_17_dialog_content = "E o carrossel é muito bonito com as luzes à noite... Você não gosta de andar a cavalo, Carleen?",
  ui_story_5057_50571102_18_dialog_content = "Além da roda-gigante...",
  ui_story_5057_50571102_19_dialog_content = "Não.",
  ui_story_5057_50571102_20_dialog_content = "Desculpe, mas isso tem a ver com... muitas coisas.",
  ui_story_5057_50571102_21_dialog_content = "O Vice é um deles?",
  ui_story_5057_50571102_22_dialog_content = "Não vou negar isso, mas isso não é tudo...",
  ui_story_5057_50571102_23_dialog_content = "Nós dois recebemos o mesmo treinamento rigoroso. Não há motivo para eu não conseguir fazer o que ela podia!",
  ui_story_5057_50571102_24_dialog_content = "Sem mencionar com você como testemunha...",
  ui_story_5057_50571102_25_dialog_content = "De qualquer forma, preciso praticar até ter a compostura de um verdadeiro cavaleiro!",
  ui_story_5057_50571102_26_dialog_content = "Primeiro alvo, Dragão da Noite Clara!",
  ui_story_5057_50571102_27_dialog_content = "<color=#e8d9bb>O primeiro passeio no Dragão da Noite Clara</color>",
  ui_story_5057_50571102_28_dialog_content = "Acho que minha faixa de cabelo acabou de ser levada pelo vento.",
  ui_story_5057_50571102_29_dialog_content = "Continue!",
  ui_story_5057_50571102_30_dialog_content = "<color=#e8d9bb>O segundo passeio no Dragão da Noite Clara</color>",
