  ui_story_5057_50571102_32_dialog_content = "De novo!",
  ui_story_5057_50571102_33_dialog_content = "<color=#e8d9bb>O terceiro passeio no Dragão da Noite Clara</color>",
  ui_story_5057_50571102_34_dialog_content = "Acho que um Eclipsita acabou de me socar no estômago... *arrrgh*",
  ui_story_5057_50571102_35_dialog_content = "Hmm... Droga!",
  ui_story_5057_50571102_36_dialog_content = "Carleen, que tal mudarmos para a Matriz Fantasia?",
  ui_story_5057_50571102_37_dialog_content = "Você já está se esforçando muito.",
  ui_story_5057_50571102_38_dialog_content = "B-Boa ideia.",
  ui_story_5057_50571102_39_dialog_content = "Acho que podemos contar isso... como aprovado.",
  ui_story_5057_50571102_40_dialog_content = "Segundo alvo, Matriz Fantasia.",
  ui_story_5057_50571102_41_dialog_content = "<color=#e8d9bb>Depois de sair da Matriz Fantasia com Carleen</color>",
  ui_story_5057_50571102_42_dialog_content = "M-Meu coração está todo lá em cima na minha garganta.",
  ui_story_5057_50571102_43_dialog_content = "Eu não me sinto tão mal quanto antes.",
  ui_story_5057_50571102_44_dialog_content = "Você não acha que é \"tão ruim\" agora?",
  ui_story_5057_50571102_45_dialog_content = "Você está se esforçando demais... Mais três vezes e eu provavelmente morrerei.",
  ui_story_5057_50571102_46_dialog_content = "Enquanto ainda tenho algo em mim, vamos tentar o Céu Azul.",
  ui_story_5057_50571102_47_dialog_content = "Não é melhor enfrentar um passeio que você não conseguiu lidar da última vez?",
  ui_story_5057_50571102_48_dialog_content = "...",
  ui_story_5057_50571102_49_dialog_content = "Ou podemos voltar e pegar comida, enquanto meu estômago ainda está intacto.",
  ui_story_5057_50571102_50_dialog_content = "Não, nunca!",
  ui_story_5057_50571102_51_dialog_content = "Estou enfrentando o Blue Sky com certeza desta vez! Se eu travar, me empurre imediatamente!",
  ui_story_5057_50571102_52_dialog_content = "Pronto?",
  ui_story_5057_50571102_53_dialog_content = "P-Por favor, conceda-me a fé para permanecer resoluto na incerteza, indomável na agitação.",
  ui_story_5057_50571102_54_option_content = "Agarre Carleen e pule",
