  ui_story_5057_50571102_61_dialog_content = "Por favor, conceda-me o—",
  ui_story_5057_50571102_62_dialog_content = "Eca-!",
  ui_story_5057_50571102_63_dialog_content = "Você está bem, Carleen? Aqui, apoie-se em mim.",
  ui_story_5057_50571102_64_dialog_content = "Obrigado, PlayerName...",
  ui_story_5057_50571102_65_dialog_content = "Depois de todo o pular e balançar, eu realmente me sinto revigorado agora.",
  ui_story_5057_50571102_66_dialog_content = "O quê? Então você está bem com o Céu Azul? Sem dor ou desconforto?",
  ui_story_5057_50571102_67_dialog_content = "Acredito que estou bem.",
  ui_story_5057_50571102_68_dialog_content = "Que vigor maravilhoso... Não, melhor dizendo, extremamente impressionante.",
  ui_story_5057_50571102_69_dialog_content = "Mas estou um pouco sedento.",
