  ui_story_5057_50571102_77_dialog_content = "Tudo bem, sou resistente o suficiente para não ficar doente tão facilmente.",
  ui_story_5057_50571102_78_dialog_content = "... Pensando bem, esqueça o que eu disse. Obrigada.",
  ui_story_5057_50571102_79_dialog_content = "Uh, o que está acontecendo?",
  ui_story_5057_50571102_80_dialog_content = "É bom poder me apoiar em você de vez em quando.",
  ui_story_5057_50571102_81_dialog_content = "Vamos voltar.",
